const money = (amount: number) => `${new Intl.NumberFormat("ru-KZ", { maximumFractionDigits: 0 }).format(amount)} ₸`;

function Brand({ compact = false }: { compact?: boolean }) {
  return <Link className={`brand ${compact ? "brand-compact" : ""}`} to="/" aria-label="TenderMarket — главная">
    <span className="brand-icon"><ShoppingCart size={20} strokeWidth={2.1} /></span>
    <span className="brand-word">Tender<span>Market</span></span>
  </Link>;
}

export function SiteHeader() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [noticeOpen, setNoticeOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [city, setCity] = useState(() => readLocal("tm_city", "Алматы"));
  const navigate = useNavigate();
  useEffect(() => { const syncCity = () => setCity(readLocal("tm_city", "Алматы")); window.addEventListener("tm-city-change", syncCity); return () => window.removeEventListener("tm-city-change", syncCity); }, []);
  const submitSearch = (event: FormEvent) => {
    event.preventDefault();
    navigate(`/catalog?q=${encodeURIComponent(query)}`);
  };
  return <header className="site-header">
    <div className="site-header-inner">
      <Brand />
      <button className="icon-button mobile-menu" aria-label="Открыть меню" onClick={() => setMenuOpen(!menuOpen)}><Menu size={20} /></button>
      <nav className={`top-nav ${menuOpen ? "top-nav-open" : ""}`} aria-label="Основная навигация">
        <NavLink to="/catalog">Каталог</NavLink>
        <NavLink to="/suppliers">Поставщики</NavLink>
        <NavLink to="/subcontracts">Субподряды</NavLink>
        <a href="#how-it-works">Как это работает</a>
      </nav>
      <label className="header-city-picker"><MapPin size={15} /><select aria-label="Ваш город" value={city} onChange={event => { setCity(event.target.value); saveLocal("tm_city", event.target.value); window.dispatchEvent(new Event("tm-city-change")); }}><option value="Весь Казахстан">Весь Казахстан</option>{kazakhstanCities.map(item => <option key={item}>{item}</option>)}</select></label>
      <form className="header-search" onSubmit={submitSearch}>
        <Search size={17} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Найти заявку, товар или поставщика" aria-label="Поиск по сайту" />
        {query && <button type="button" className="search-clear" onClick={() => setQuery("")} aria-label="Очистить поиск"><X size={14} /></button>}
      </form>
      <div className="header-actions">
        <button className="language-button" aria-label="Выбрать язык"><Globe2 size={17} /><span>Рус</span><ChevronDown size={14} /></button>
        <div className="popover-anchor">
          <button className="icon-button notification-button" aria-label="Уведомления" onClick={() => setNoticeOpen(!noticeOpen)}><Bell size={19} /><span className="notification-dot" /></button>
          {noticeOpen && <div className="notification-popover"><div className="popover-title">Уведомления <span className="pill pill-blue">2 новых</span></div><div className="notice-row"><span className="notice-icon"><Package size={17} /></span><span><b>Новая заявка рядом</b><small>Смешанный список товаров · Алматы</small></span><time>5 мин</time></div><div className="notice-row"><span className="notice-icon mint"><MessageCircle size={17} /></span><span><b>Ответ от поставщика</b><small>TechnoPlus обновил предложение</small></span><time>1 ч</time></div><Link to="/supplier/inbox" className="popover-link" onClick={() => setNoticeOpen(false)}>Все уведомления <ArrowRight size={15} /></Link></div>}
        </div>
        <Link className="login-link" to="/auth"><UserRound size={18} /><span>Войти</span></Link>
        <Link className="button button-primary header-cta" to="/request/new"><Send size={15} />Создать заявку</Link>
      </div>
    </div>
  </header>;
}

export function Footer() {
  return <footer className="site-footer"><div className="footer-main"><div className="footer-brand"><Brand /><p>Поставки становятся проще,<br />когда всё собрано в одном месте.</p></div><div><strong>Покупателям</strong><Link to="/request/new">Создать заявку</Link><Link to="/catalog">Каталог товаров</Link><Link to="/customer">Мои закупки</Link></div><div><strong>Поставщикам</strong><Link to="/supplier/inbox">Подходящие заявки</Link><Link to="/suppliers">Каталог поставщиков</Link><Link to="/supplier/inbox">Мои предложения</Link></div><div><strong>Помощь</strong><a href="#how-it-works">Как это работает</a><a href="mailto:support@tendermarket.kz">Поддержка</a><Link to="/admin">Администрирование</Link></div></div><div className="footer-bottom"><span>© 2026 TenderMarket</span><span>Условия · Конфиденциальность</span><span className="footer-location"><MapPin size={14} /> Казахстан</span></div></footer>;
}

function SectionHeading({ eyebrow, title, action, to }: { eyebrow?: string; title: string; action?: string; to?: string }) {
  return <div className="section-heading"><div>{eyebrow && <div className="section-eyebrow">{eyebrow}</div>}<h2>{title}</h2></div>{action && <Link className="text-link" to={to ?? "/catalog"}>{action}<ArrowRight size={17} /></Link>}</div>;
}

function RequestDialog({ open, onClose, initialProduct, onDone }: { open: boolean; onClose: () => void; initialProduct?: Product; onDone: (message: string, requestId: string) => void }) {
  const [itemType, setItemType] = useState<"PRODUCT" | "SERVICE">("PRODUCT");
  const [items, setItems] = useState(() => initialProduct ? [{ name: initialProduct.name, qty: "1", unit: "шт.", detail: initialProduct.subtitle, category: categories.find(category => category.id === initialProduct.category || category.name === initialProduct.category)?.id ?? "" }] : [{ name: "", qty: "", unit: "шт.", detail: "", category: "" }]);
  const [coverage, setCoverage] = useState("all");
  const [region, setRegion] = useState(() => readLocal("tm_city", "Алматы"));
  const [deadline, setDeadline] = useState("");
  const [sending, setSending] = useState(false);
  const [error, setError] = useState("");
  const [attachments, setAttachments] = useState<Array<{ id: string; originalName: string }>>([]);
  if (!open) return null;
  const setItem = (index: number, key: keyof typeof items[number], value: string) => setItems(current => current.map((item, i) => i === index ? { ...item, [key]: value } : item));
  const submit = async (event: FormEvent) => {
    event.preventDefault();
    const cleanItems = items.filter(item => item.name.trim() && Number(item.qty) > 0);
    if (!cleanItems.length) { setError("Добавьте хотя бы одну товарную позицию с количеством."); return; }
    setSending(true); setError("");
    const payload = { title: cleanItems.length === 1 ? cleanItems[0].name : `Заявка (${itemType === "SERVICE" ? "Услуги" : "Товары"}): ${cleanItems.length} поз.`, type: itemType, region, deliveryDeadline: deadline || null, coverageMode: coverage, attachments: attachments.map(file => file.id), items: cleanItems.map(item => ({ name: item.name, type: itemType, quantity: Number(item.qty), unit: item.unit, details: item.detail, category: item.category || undefined })) };
    try {
      const created = await apiRequest<{ id: string }>("/requests", { method: "POST", body: JSON.stringify(payload) });
      onDone(`Заявка опубликована. Её увидят подходящие поставщики. № ${created.id.slice(0, 8)}`, created.id);
    } catch {
      setError("Не удалось опубликовать заявку. Войдите в аккаунт и проверьте подключение сервера.");
      setSending(false);
      return;
    }
    setSending(false);
  };
  const uploadRequestFiles = async (files: FileList | null) => {
    if (!files?.length) return;
    try { const uploaded = await Promise.all(Array.from(files).map(file => apiUpload<{ id: string; originalName: string }>(file))); setAttachments(current => [...current, ...uploaded]); setError(""); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Не удалось загрузить файл."); }
  };
  const units = itemType === "SERVICE" ? ["усл.", "час", "смена", "проект", "месяц", "м²"] : ["шт.", "кг", "л", "упак.", "набор", "м"];
  return <div className="modal-backdrop" role="presentation" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><section className="request-modal" role="dialog" aria-modal="true" aria-labelledby="request-title"><div className="modal-head"><div><span className="eyebrow">Бесплатно · займёт пару минут</span><h2 id="request-title">{itemType === "SERVICE" ? "Заказ услуг и работ" : "Что нужно найти?"}</h2><p>{itemType === "SERVICE" ? "Опишите требуемые услуги или работы — подрядчики рассчитают смету." : "Опишите закупку — поставщики подготовят цены и сроки."}</p></div><button className="icon-button" onClick={onClose} aria-label="Закрыть"><X size={20} /></button></div><div className="segment-toggle" style={{ margin: "12px 0 16px" }}><button type="button" className={itemType === "PRODUCT" ? "active" : ""} onClick={() => { setItemType("PRODUCT"); setItems(curr => curr.map(it => ({ ...it, unit: it.unit === "усл." ? "шт." : it.unit }))); }}>Закупка товаров</button><button type="button" className={itemType === "SERVICE" ? "active" : ""} onClick={() => { setItemType("SERVICE"); setItems(curr => curr.map(it => ({ ...it, unit: it.unit === "шт." ? "усл." : it.unit }))); }}>Заказ услуг и работ</button></div><form onSubmit={submit} className="request-form"><div className="manage-upload"><label className="file-upload"><input type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx" onChange={event => void uploadRequestFiles(event.target.files)} /><Paperclip size={15} />Приложить ТЗ, смету, фото или документы</label>{attachments.map(file => <span key={file.id} className="file-pill"><FileText size={14} />{file.originalName}</span>)}</div><div className="form-section-label">{itemType === "SERVICE" ? "Услуги и работы" : "Товары в заявке"} <span>{items.length} {items.length === 1 ? "позиция" : "позиции"}</span></div><div className="request-line-list">{items.map((item, index) => <div className="request-line" key={index}><div className="line-index">{String(index + 1).padStart(2, "0")}</div><div className="line-fields"><label className="field-grow"><span>{itemType === "SERVICE" ? "Наименование услуги / работы" : "Название товара"}</span><input required value={item.name} onChange={event => setItem(index, "name", event.target.value)} placeholder={itemType === "SERVICE" ? "Например, монтаж оборудования или клининг" : "Например, ноутбук или свежие яблоки"} /></label><label className="quantity-field"><span>{itemType === "SERVICE" ? "Объём" : "Количество"}</span><input required min="0.01" step="any" type="number" value={item.qty} onChange={event => setItem(index, "qty", event.target.value)} placeholder="1" /></label><label className="unit-field"><span>Ед.</span><select value={item.unit} onChange={event => setItem(index, "unit", event.target.value)}>{units.map(u => <option key={u}>{u}</option>)}</select></label>{items.length > 1 && <button type="button" className="line-remove" onClick={() => setItems(items.filter((_, i) => i !== index))} aria-label="Удалить позицию"><X size={17} /></button>}</div><div className="line-detail"><label><span>Категория</span><select value={item.category} onChange={event => setItem(index, "category", event.target.value)}><option value="">Выберите для точного подбора</option>{categories.map(category => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label><label><span>{itemType === "SERVICE" ? "Требования, ТЗ или условия" : "Характеристики или комментарий"}</span><input value={item.detail} onChange={event => setItem(index, "detail", event.target.value)} placeholder={itemType === "SERVICE" ? "Сроки, допуски, оборудование исполнителя" : "Модель, размер, аналог, важные условия"} /></label></div></div>)}</div><button type="button" className="add-line-button" onClick={() => setItems([...items, { name: "", qty: "", unit: itemType === "SERVICE" ? "усл." : "шт.", detail: "", category: "" }])}><Plus size={16} />Добавить {itemType === "SERVICE" ? "услугу" : "товар"}</button><div className="form-grid"><label><span>{itemType === "SERVICE" ? "Место оказания услуг" : "Куда доставить"}</span><select value={region} onChange={event => setRegion(event.target.value)}><option value="Весь Казахстан">Весь Казахстан</option>{kazakhstanCities.map(city => <option key={city}>{city}</option>)}</select></label><label><span>Желаемый срок</span><input type="date" value={deadline} onChange={event => setDeadline(event.target.value)} /></label></div><fieldset className="coverage-field"><legend>Какие предложения подходят?</legend><label className={`coverage-option ${coverage === "all" ? "selected" : ""}`}><input type="radio" name="coverage" value="all" checked={coverage === "all"} onChange={() => setCoverage("all")} /><span className="radio-mark" /><span><strong>На весь список</strong><small>{itemType === "SERVICE" ? "Подрядчик закроет все позиции под ключ" : "Поставщик закроет все позиции одной поставкой"}</small></span><CheckCircle2 className="coverage-check" size={17} /></label><label className={`coverage-option ${coverage === "partial" ? "selected" : ""}`}><input type="radio" name="coverage" value="partial" checked={coverage === "partial"} onChange={() => setCoverage("partial")} /><span className="radio-mark" /><span><strong>Можно частично</strong><small>Подойдут цены на одну или несколько позиций</small></span><CheckCircle2 className="coverage-check" size={17} /></label></fieldset>{error && <div className="form-error" role="alert">{error} <Link to="/auth">Войти в аккаунт</Link></div>}<div className="modal-actions"><button type="button" className="button button-secondary" onClick={onClose}>Сохранить на потом</button><button className="button button-primary" disabled={sending}>{sending ? "Публикуем…" : "Опубликовать заявку"}<ArrowRight size={16} /></button></div></form></section></div>;
}

function HomePage() {
  const [search, setSearch] = useState("");
  const [modal, setModal] = useState(false);
  const [selected, setSelected] = useState<Product | undefined>();
  const [toast, setToast] = useState("");
  const [favorites, setFavorites] = useState<string[]>(() => readLocal("tm_favorites", []));
  const [searchParams] = useSearchParams();
  const carousel = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();
  const submitSearch = (event: FormEvent) => { event.preventDefault(); navigate(`/catalog?q=${encodeURIComponent(search)}`); };
  const showToast = (message: string, requestId: string) => { setToast(message); window.setTimeout(() => navigate(`/customer?created=${encodeURIComponent(requestId)}`), 650); };
  const startRequest = (product?: Product) => { setSelected(product); setModal(true); };
  const toggleFavorite = (id: string) => setFavorites(current => { const next = current.includes(id) ? current.filter(item => item !== id) : [...current, id]; saveLocal("tm_favorites", next); return next; });
  return <><SiteHeader /><main>
    <section className="hero-shell"><div className="hero-copy"><div className="hero-kicker"><span className="kicker-dot" />Универсальный маркетплейс закупок</div><h1>Опишите, что вам нужно —<br /><span>получите предложения</span> от поставщиков</h1><p className="hero-description">Любые товары для дома, бизнеса и повседневных задач.<br className="desktop-only" /> Сравнивайте цены и условия в одном месте.</p><form className="hero-search" onSubmit={submitSearch}><Search size={19} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Поиск по товарам, категориям и поставщикам…" aria-label="Поиск по товарам, категориям и поставщикам" /><button className="button button-primary" type="submit">Найти</button></form><div className="hero-points"><span><ShieldCheck size={17} />Проверенные поставщики</span><i /><span><Truck size={17} />Предложения с доставкой</span><i /><span><Clock3 size={17} />Экономия времени</span></div></div><div className="hero-art" aria-hidden="true"><div className="hero-orbit orbit-one" /><div className="hero-orbit orbit-two" /><img src="/products/laptop.png" alt="" className="hero-laptop" /><div className="hero-note note-top"><span className="note-check"><Check size={13} /></span><span>Ваш список товаров<br /><b>уже сравнивают</b></span></div><div className="hero-note note-bottom"><span className="note-icon"><Sparkles size={17} /></span><span><b>Больше выбора</b><small>для любых задач</small></span></div></div></section>

    <section className="trust-strip" aria-label="Преимущества"><span><span className="trust-icon"><BadgeCheck size={17} /></span>Проверенные поставщики</span><span><span className="trust-icon"><ListChecks size={17} /></span>Цены по каждой позиции</span><span><span className="trust-icon"><ShieldCheck size={17} /></span>Прозрачные условия</span><span><span className="trust-icon"><MessageCircle size={17} /></span>Всё общение в одном месте</span></section>

    <section className="content-section categories-section" id="categories"><SectionHeading eyebrow="Большой выбор, понятный поиск" title="Популярные категории" action="Все категории" to="/catalog" /><div className="category-grid">{categories.map((category, index) => <Link key={category.id} to={`/catalog?category=${category.id}`} className={`category-tile category-${index}`}><div className="category-image-wrap"><img src={category.image} alt="" loading={index > 3 ? "lazy" : "eager"} /></div><div className="category-copy"><strong>{category.name}</strong><span>{category.description}</span></div><span className="category-arrow"><ArrowUpRight size={15} /></span></Link>)}</div></section>

    <section className="content-section products-section"><div className="section-heading"><div><div className="section-eyebrow">Выбор недели</div><h2>Популярные товары</h2></div><div className="carousel-controls"><Link className="text-link desktop-only" to="/catalog">Весь каталог <ArrowRight size={16} /></Link><button className="icon-button carousel-arrow" aria-label="Предыдущие товары" onClick={() => carousel.current?.scrollBy({ left: -440, behavior: "smooth" })}><ChevronLeft size={19} /></button><button className="icon-button carousel-arrow active" aria-label="Следующие товары" onClick={() => carousel.current?.scrollBy({ left: 440, behavior: "smooth" })}><ChevronRight size={19} /></button></div></div><div className="product-carousel" ref={carousel}>{products.map(product => <article className="product-card" key={product.id}><div className="product-image"><Link to={`/catalog?q=${encodeURIComponent(product.name)}`}><img src={product.image} alt={product.name} loading="lazy" /></Link><button className={`favorite-button ${favorites.includes(product.id) ? "is-favorite" : ""}`} aria-label={favorites.includes(product.id) ? "Убрать из избранного" : "В избранное"} onClick={() => toggleFavorite(product.id)}><Heart size={17} fill={favorites.includes(product.id) ? "currentColor" : "none"} /></button></div><div className="product-info"><span className="product-category">{product.category}</span><Link className="product-name" to={`/catalog?q=${encodeURIComponent(product.name)}`}>{product.name}</Link><span className="product-subtitle">{product.subtitle}</span><div className="product-card-bottom"><span className="product-price">от {money(product.price)}</span><button className="quick-request" title="Запросить предложение" onClick={() => startRequest(product)}><ShoppingCart size={16} /></button></div><span className="product-supplier"><BadgeCheck size={13} />{product.supplier}</span></div></article>)}</div><div className="carousel-progress"><span /><span /><span /><span /><span className="progress-active" /></div></section>

    <section className="supplier-section content-section"><SectionHeading eyebrow="Партнёры, которым доверяют" title="Проверенные поставщики" action="Все поставщики" to="/suppliers" /><div className="supplier-grid">{suppliers.map(supplier => <Link to="/suppliers" className="supplier-card" key={supplier.name}><div className={`supplier-mark ${supplier.tone}`}>{supplier.mark}</div><div className="supplier-meta"><span className="supplier-title">{supplier.name}<BadgeCheck size={15} /></span><span>{supplier.category}</span><span className="supplier-place"><MapPin size={12} />{supplier.city}<i />{supplier.products}</span></div><ChevronRight className="supplier-next" size={16} /></Link>)}</div></section>

    <section className="how-section content-section" id="how-it-works"><SectionHeading eyebrow="От потребности до поставки" title="Как это работает" /><div className="steps-grid"><article className="step-item"><div className="step-number">01</div><div className="step-icon"><FileText size={22} /></div><h3>Создайте заявку</h3><p>Добавьте товары, количество и удобные условия доставки.</p><Link to="/request/new" className="step-link">Заполнить список <ArrowRight size={15} /></Link></article><div className="step-connector"><ArrowRight size={20} /></div><article className="step-item"><div className="step-number">02</div><div className="step-icon"><MessageCircle size={22} /></div><h3>Получите предложения</h3><p>Подходящие поставщики укажут цены и наличие по строкам.</p><Link to="/supplier/inbox" className="step-link">Для поставщиков <ArrowRight size={15} /></Link></article><div className="step-connector"><ArrowRight size={20} /></div><article className="step-item"><div className="step-number">03</div><div className="step-icon"><CheckCircle2 size={22} /></div><h3>Выберите лучшее</h3><p>Сравните сумму, сроки и условия, затем обсудите детали в чате.</p><Link to="/customer" className="step-link">Мои закупки <ArrowRight size={15} /></Link></article></div><div className="how-cta"><div className="how-cta-icon"><Sparkles size={20} /></div><div><strong>Есть список товаров? Начните с него.</strong><span>Поставщики сами подготовят предложения.</span></div><button className="button button-primary" onClick={() => startRequest()}>Создать заявку <ArrowRight size={16} /></button></div></section>

    <section className="seller-banner"><div className="seller-banner-mark"><BriefcaseBusiness size={23} /></div><div className="seller-banner-copy"><span>Для бизнеса и поставщиков</span><h2>Больше клиентов — меньше ручной работы</h2><p>Получайте подходящие заявки и рассчитывайте целые списки за пару минут.</p></div><Link to="/supplier/inbox" className="button button-on-blue">Открыть кабинет поставщика <ArrowRight size={16} /></Link><div className="seller-banner-orb" /></section>
  </main><Footer />{modal && <RequestDialog open={modal} initialProduct={selected} onClose={() => setModal(false)} onDone={showToast} />}{toast && <div role="status" className="toast-message"><CheckCircle2 size={18} />{toast}</div>}</>;
}

function CatalogPage() {
  const navigate = useNavigate();
  const [params, setParams] = useSearchParams();
  const [itemType, setItemType] = useState<"ALL" | "PRODUCT" | "SERVICE">((params.get("type") as any) || "ALL");
  const [query, setQuery] = useState(params.get("q") ?? "");
  const [activeCategory, setActiveCategory] = useState(params.get("category") ?? "all");
  const [sort, setSort] = useState("popular");
  const [modalProduct, setModalProduct] = useState<Product>();
  const [toast, setToast] = useState("");
  const [catalogRows, setCatalogRows] = useState<Array<{ id: string; name: string; type?: "PRODUCT" | "SERVICE"; description: string | null; price: string | number | null; unit: string; media?: { image?: string } | null; category: { id: string; slug: string; name: string }; organization: { name: string } }>>([]);
  const [catalogCategories, setCatalogCategories] = useState<Array<{ id: string; slug: string; name: string }>>([]);
  const [catalogLoading, setCatalogLoading] = useState(true);
  const [catalogError, setCatalogError] = useState("");
  const [region, setRegion] = useState(() => readLocal<string>("tm_city", "Алматы"));
  useEffect(() => { const sync = () => setRegion(readLocal<string>("tm_city", "Алматы")); window.addEventListener("tm-city-change", sync); return () => window.removeEventListener("tm-city-change", sync); }, []);
  useEffect(() => {
    setCatalogLoading(true); setCatalogError("");
    const search = new URLSearchParams();
    if (query.trim()) search.set("q", query.trim());
    if (activeCategory !== "all") search.set("category", activeCategory);
    if (region !== "Весь Казахстан") search.set("region", region);
    if (itemType !== "ALL") search.set("type", itemType);
    Promise.all([apiRequest<typeof catalogRows>(`/products${search.size ? `?${search}` : ""}`), apiRequest<typeof catalogCategories>("/categories")])
      .then(([rows, allCategories]) => { setCatalogRows(rows); setCatalogCategories(allCategories); })
      .catch(error => setCatalogError(error instanceof Error ? error.message : "Не удалось загрузить каталог."))
      .finally(() => setCatalogLoading(false));
  }, [query, activeCategory, region, itemType]);
  const filtered = useMemo(() => sort === "price" ? [...catalogRows].sort((a, b) => Number(a.price ?? Infinity) - Number(b.price ?? Infinity)) : catalogRows, [catalogRows, sort]);
  const setCategory = (id: string) => { setActiveCategory(id); setParams(current => { const next = new URLSearchParams(current); if (id === "all") next.delete("category"); else next.set("category", id); return next; }); };
  const makeProduct = (row: (typeof catalogRows)[number]): Product => ({ id: row.id, name: row.name, subtitle: row.description || row.unit, price: Number(row.price ?? 0), category: row.category.slug, image: row.media?.image || `/products/${row.category.slug === "furniture" ? "office-chair" : row.category.slug === "food" ? "grocery-set" : "laptop"}.png`, supplier: row.organization.name });
  return <><SiteHeader /><main className="page-wrap catalog-page"><div className="breadcrumbs"><Link to="/">Главная</Link><ChevronRight size={14} /><span>Каталог</span></div><div className="catalog-title-row"><div><div className="section-eyebrow">Каталог товаров и услуг</div><h1>Найдите то, что нужно</h1><p>Актуальные товары и услуги из витрин поставщиков в выбранном городе.</p></div><Link to="/request/new" className="button button-primary"><Plus size={16} />Создать заявку</Link></div><div className="catalog-toolbar"><div className="catalog-search"><Search size={17} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Название товара, услуги или поставщика" /><button className="button button-primary" onClick={() => setParams(query ? { q: query } : {})}>Найти</button></div><label className="sort-control"><SlidersHorizontal size={16} /><span>Сначала</span><select value={sort} onChange={event => setSort(event.target.value)}><option value="popular">новые</option><option value="price">дешевле</option></select></label></div><div className="segment-toggle" style={{ margin: "10px 0 14px" }}><button className={itemType === "ALL" ? "active" : ""} onClick={() => { setItemType("ALL"); setParams(p => { const next = new URLSearchParams(p); next.delete("type"); return next; }); }}>Все (товары и услуги)</button><button className={itemType === "PRODUCT" ? "active" : ""} onClick={() => { setItemType("PRODUCT"); setParams(p => { const next = new URLSearchParams(p); next.set("type", "PRODUCT"); return next; }); }}>Товары</button><button className={itemType === "SERVICE" ? "active" : ""} onClick={() => { setItemType("SERVICE"); setParams(p => { const next = new URLSearchParams(p); next.set("type", "SERVICE"); return next; }); }}>Услуги и работы</button></div><div className="catalog-categories"><button className={activeCategory === "all" ? "active" : ""} onClick={() => setCategory("all")}>Все категории</button>{catalogCategories.map(category => <button className={activeCategory === category.slug ? "active" : ""} onClick={() => setCategory(category.slug)} key={category.id}>{category.name}</button>)}</div><div className="catalog-result-line">Найдено позиций: <strong>{filtered.length}</strong><span>·</span> {region}</div>{catalogError ? <div className="empty-state"><strong>Не удалось загрузить каталог</strong><span>{catalogError}</span><button className="button button-secondary" onClick={() => setQuery(current => `${current} `)}>Повторить</button></div> : catalogLoading ? <div className="empty-state">Загружаем позиции…</div> : <div className="catalog-product-grid">{filtered.map(row => { const product = makeProduct(row); return <article className="product-card" key={row.id}><div className="product-image"><img src={product.image} alt={product.name} loading="lazy" /><span className="catalog-availability"><Check size={12} />В наличии</span></div><div className="product-info"><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><span className="product-category">{row.category.name}</span><span className={`item-type-pill ${row.type === "SERVICE" ? "type-service" : "type-product"}`}>{row.type === "SERVICE" ? "Услуга" : "Товар"}</span></div><strong className="product-name">{row.name}</strong><span className="product-subtitle">{row.description || row.unit}</span><span className="product-price">{row.price ? `от ${money(Number(row.price))}` : "Цена по запросу"}</span><span className="product-supplier"><BadgeCheck size={13} />{row.organization.name}</span><button className="button button-secondary full-button" onClick={() => setModalProduct(product)}>Запросить предложение</button></div></article>; })}</div>}{!catalogLoading && !catalogError && filtered.length === 0 && <div className="empty-state"><Search size={25} /><strong>В каталоге пока нет позиций</strong><span>Поставщики добавят товары и услуги в свои витрины, а вы можете сразу создать заявку.</span><Link to="/request/new" className="button button-secondary">Создать заявку</Link></div>}</main><Footer />{modalProduct && <RequestDialog open initialProduct={modalProduct} onClose={() => setModalProduct(undefined)} onDone={(message, requestId) => { setToast(message); window.setTimeout(() => navigate(`/customer?created=${encodeURIComponent(requestId)}`), 650); }} />}{toast && <div className="toast-message"><CheckCircle2 size={18} />{toast}</div>}</>;
}

type SupplierListing = { id: string; name: string; organizationName: string; about: string | null; categories: Array<{ id: string; slug: string; name: string }>; regions: string[]; rating: number; reviewCount: number; productCount: number; verified: boolean };

function SuppliersPage() {
  const [params, setParams] = useSearchParams();
  const [query, setQuery] = useState(params.get("q") ?? "");
  const [category, setCategory] = useState(params.get("category") ?? "all");
  const [region, setRegion] = useState(params.get("region") ?? (readLocal<string>("tm_city", "Алматы") === "Весь Казахстан" ? "" : readLocal<string>("tm_city", "Алматы")));
  const [results, setResults] = useState<SupplierListing[]>([]);
  const [supplierCategories, setSupplierCategories] = useState<Array<{ id: string; slug: string; name: string }>>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  useEffect(() => {
    setLoading(true); setError("");
    const search = new URLSearchParams();
    if (query.trim()) search.set("q", query.trim());
    if (category !== "all") search.set("category", category);
    if (region) search.set("region", region);
    Promise.all([apiRequest<SupplierListing[]>(`/suppliers${search.size ? `?${search}` : ""}`), apiRequest<Array<{ id: string; slug: string; name: string }>>("/categories")])
      .then(([listedSuppliers, allCategories]) => { setResults(listedSuppliers); setSupplierCategories(allCategories); })
      .catch(cause => setError(cause instanceof Error ? cause.message : "Не удалось загрузить поставщиков."))
      .finally(() => setLoading(false));
  }, [query, category, region]);
  const updateParams = (next: { q?: string; category?: string; region?: string }) => {
    const search = new URLSearchParams();
    if (next.q) search.set("q", next.q);
    if (next.category && next.category !== "all") search.set("category", next.category);
    if (next.region) search.set("region", next.region);
    setParams(search);
  };
  useEffect(() => {
    const syncCity = () => { const city = readLocal<string>("tm_city", "Алматы"); const selected = city === "Весь Казахстан" ? "" : city; setRegion(selected); setParams(current => { const next = new URLSearchParams(current); if (selected) next.set("region", selected); else next.delete("region"); return next; }); };
    window.addEventListener("tm-city-change", syncCity);
    return () => window.removeEventListener("tm-city-change", syncCity);
  }, [setParams]);
  const reset = () => { setQuery(""); setCategory("all"); setRegion(""); updateParams({}); };
  return <><SiteHeader /><main className="page-wrap catalog-page"><div className="breadcrumbs"><Link to="/">Главная</Link><ChevronRight size={14} /><span>Поставщики</span></div><div className="catalog-title-row"><div><div className="section-eyebrow">Проверенные компании</div><h1>Поставщики</h1><p>Выберите категорию и город, чтобы найти партнёров поблизости.</p></div><Link to="/supplier/inbox" className="button button-primary">Кабинет поставщика <ArrowRight size={16} /></Link></div><div className="supplier-filters"><div className="catalog-search"><Search size={17} /><input value={query} onChange={event => { setQuery(event.target.value); updateParams({ q: event.target.value, category, region }); }} placeholder="Компания, товар или категория" aria-label="Поиск поставщика" />{query && <button className="search-clear" onClick={() => { setQuery(""); updateParams({ category, region }); }} aria-label="Очистить поиск"><X size={14} /></button>}</div><label className="supplier-filter-control"><span>Город доставки</span><select value={region} onChange={event => { const selected = event.target.value; setRegion(selected); saveLocal("tm_city", selected || "Весь Казахстан"); window.dispatchEvent(new Event("tm-city-change")); updateParams({ q: query, category, region: selected }); }}><option value="">Все города</option>{kazakhstanCities.map(city => <option key={city}>{city}</option>)}</select></label><span className="supplier-filter-count"><SlidersHorizontal size={15} />{loading ? "Ищем…" : `${results.length} поставщиков`}</span></div><div className="supplier-category-filters" aria-label="Фильтр по категориям"><button className={category === "all" ? "active" : ""} onClick={() => { setCategory("all"); updateParams({ q: query, category: "all", region }); }}>Все категории</button>{supplierCategories.map(item => <button key={item.id} className={category === item.slug ? "active" : ""} onClick={() => { setCategory(item.slug); updateParams({ q: query, category: item.slug, region }); }}>{item.name}</button>)}</div><div className="catalog-result-line">Категория: <strong>{category === "all" ? "Все" : supplierCategories.find(item => item.slug === category)?.name ?? "выбрана"}</strong><span>·</span> Город: <strong>{region || "Все города"}</strong><button className="text-link-button" onClick={reset}>Сбросить</button></div>{error ? <div className="empty-state"><strong>Не удалось загрузить каталог</strong><span>{error}</span><button className="button button-secondary" onClick={() => setQuery(current => `${current} `)}>Повторить</button></div> : loading ? <div className="empty-state">Загружаем каталог поставщиков…</div> : <div className="supplier-list">{results.map(supplier => <article className="supplier-list-row" key={supplier.id}><div className="supplier-mark blue">{supplier.name.slice(0, 2).toUpperCase()}</div><div className="supplier-meta"><span className="supplier-title">{supplier.name}{supplier.verified && <BadgeCheck size={15} />}</span><span>{supplier.about || supplier.organizationName}</span><span className="supplier-category-tags">{supplier.categories.map(item => <span key={item.id}>{item.name}</span>)}</span><span className="supplier-place"><MapPin size={12} />{supplier.regions.length ? supplier.regions.join(", ") : "Доставка по Казахстану"}<i />{supplier.productCount} товаров</span></div><div className="supplier-rating"><Star size={15} fill="currentColor" />{supplier.rating ? supplier.rating.toLocaleString("ru-KZ", { maximumFractionDigits: 1 }) : "Новый"} <span>· {supplier.reviewCount} отзывов</span></div><Link className="button button-secondary" to="/request/new">Запросить предложение</Link></article>)}</div>}{!loading && !error && results.length === 0 && <div className="empty-state"><Search size={24} /><strong>Поставщики не найдены</strong><span>Попробуйте другую категорию, регион или запрос.</span><button className="button button-secondary" onClick={reset}>Сбросить фильтры</button></div>}</main><Footer /></>;
}

export function PortalHeader({ title, role, notifications: _notifications = 2 }: { title: string; role: string; notifications?: number }) {
  const hasSession = Boolean(readLocal("tm_access_token", ""));
  const [noticeOpen, setNoticeOpen] = useState(false);
  const [noticeList, setNoticeList] = useState<Array<{ id: string; title: string; body: string; status: string; createdAt: string; payload?: { dealId?: string; requestId?: string } }>>([]);
  useEffect(() => { if (hasSession) apiRequest<typeof noticeList>("/notifications").then(setNoticeList).catch(() => setNoticeList([])); }, [hasSession]);
  const unreadCount = noticeList.filter(item => item.status !== "READ").length;
  const markNoticeRead = (notice: (typeof noticeList)[number]) => { setNoticeOpen(false); if (notice.status !== "READ") apiRequest(`/notifications/${notice.id}/read`, { method: "POST" }).then(() => setNoticeList(current => current.map(item => item.id === notice.id ? { ...item, status: "READ" } : item))).catch(() => undefined); };
  return <div className="portal-topbar"><Brand compact /><div className="portal-search"><Search size={17} /><input placeholder="Поиск по заявкам, товарам или поставщикам" /></div><div className="portal-actions"><div className="popover-anchor"><button className="icon-button notification-button" onClick={() => setNoticeOpen(!noticeOpen)} aria-label="Уведомления"><Bell size={19} />{unreadCount > 0 && <span className="notification-dot" />}</button>{noticeOpen && <div className="notification-popover"><div className="popover-title">Уведомления</div>{noticeList.length ? noticeList.slice(0, 6).map(notice => <Link className="notice-row" key={notice.id} to={notice.payload?.dealId ? `/deals/${notice.payload.dealId}` : notice.payload?.requestId ? "/supplier/inbox" : "/customer"} onClick={() => markNoticeRead(notice)}><span className="notice-icon"><Bell size={17} /></span><span><b>{notice.title}</b><small>{notice.body}</small></span><time>{new Intl.DateTimeFormat("ru-KZ", { day: "numeric", month: "short" }).format(new Date(notice.createdAt))}</time></Link>) : <div className="notice-row"><span className="notice-icon"><Bell size={17} /></span><span><b>{hasSession ? "Пока нет уведомлений" : "Войдите, чтобы получать уведомления"}</b><small>{hasSession ? "Новые ответы появятся здесь." : "Сообщим о новых заявках и предложениях."}</small></span></div>}</div>}</div>{hasSession ? <button className="user-menu"><span className="user-avatar">{role === "Поставщик" ? "П" : "З"}</span><span><strong>{role}</strong><small>Аккаунт</small></span><ChevronDown size={15} /></button> : <Link className="user-menu" to="/auth"><span className="user-avatar"><UserRound size={16} /></span><span><strong>Войти</strong><small>{title}</small></span></Link>}</div></div>;
}

export function PortalSidebar({ active }: { active: string }) {
  const supplier = readLocal<string>("tm_user_role", "") === "SUPPLIER";
  const links = [{ label: "Найти заявки", icon: Search, to: "/supplier/inbox" }, { label: "Мои запросы", icon: FileText, to: "/customer" }, { label: "Мои предложения", icon: Send, to: "/supplier/inbox" }, { label: "Субподряды", icon: Handshake, to: "/subcontracts" }, ...(supplier ? [{ label: "Мои товары", icon: Package, to: "/supplier/products" }, { label: "Реклама", icon: Sparkles, to: "/supplier/ads" }] : []), { label: "Сообщения", icon: MessageCircle, to: "/customer" }, { label: "Каталог", icon: LayoutDashboard, to: "/catalog" }, { label: "Профиль", icon: UserRound, to: "/suppliers" }];
  return <aside className="portal-sidebar"><div className="sidebar-section-label">Рабочее пространство</div>{links.map(item => <Link to={item.to} key={item.label} className={`sidebar-link ${active === item.label ? "active" : ""}`}><item.icon size={18} /><span>{item.label}</span>{item.label === "Мои запросы" && active === item.label && <span className="sidebar-count">12</span>}</Link>)}<div className="sidebar-bottom"><button className="sidebar-link"><CircleHelp size={18} /><span>Помощь и поддержка</span></button><div className="sidebar-profile"><span className="user-avatar">АП</span><span><strong>Анна Петрова</strong><small>Профиль поставщика</small></span><ChevronDown size={15} /></div></div></aside>;
}

function SupplierWorkspace() {
  const [selectedRequest, setSelectedRequest] = useState(0);
  const [prices, setPrices] = useState(() => quoteItems.map(item => String(item.price)));
  const [coverageOnly, setCoverageOnly] = useState(true);
  const [delivery, setDelivery] = useState("25000");
  const [files, setFiles] = useState<string[]>([]);
  const [toast, setToast] = useState("");
  const [status, setStatus] = useState("Открыт");
  const requests = ["Офисные товары, электроника, мебель и продукты", "Медицинские расходники и средства гигиены", "Спецодежда и обувь", "Продукты питания для столовой", "Ноутбуки и периферия", "Мебель для офиса", "Товары для дома", "Текстиль и форма"];
  const total = quoteItems.reduce((sum, item, index) => sum + item.qty * (Number(prices[index]) || 0), 0) + (Number(delivery) || 0);
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 3600); };
  const sendOffer = async () => {
    const payload = { supplierName: "ИП Султанов А. К.", currency: "KZT", deliveryPrice: Number(delivery), total, fullCoverage: true, deliveryDate: "2026-05-15", items: quoteItems.map((item, index) => ({ requestItemId: item.id, unitPrice: Number(prices[index]) || 0, available: true })) };
    try { await apiRequest("/requests/demo/offers", { method: "POST", body: JSON.stringify(payload) }); notify("Предложение отправлено заказчику."); }
    catch { saveLocal("tm_offer_draft", payload); notify("Предложение сохранено локально. Подключите API для отправки заказчику."); }
    setStatus("Предложение отправлено");
  };
  const saveDraft = () => { saveLocal("tm_offer_draft", { prices, delivery, files, fullCoverage: true }); notify("Черновик предложения сохранён."); };
  return <div className="portal-shell"><PortalHeader title="Подходящие заявки" role="Поставщик" /><div className="portal-layout"><PortalSidebar active="Мои предложения" /><div className="request-list-panel"><div className="request-list-head"><div><h2>Мои подходящие заявки</h2><span>Заявки по вашим категориям</span></div><button className="icon-button" aria-label="Фильтры"><SlidersHorizontal size={18} /></button></div><div className="request-tabs"><button className="active">Все <b>12</b></button><button>Новые <b>5</b></button><button>В работе <b>3</b></button><button>Архив <b>4</b></button></div><div className="request-list">{requests.map((request, index) => <button key={request} className={`request-list-item ${selectedRequest === index ? "selected" : ""}`} onClick={() => setSelectedRequest(index)}><span className="request-list-title">{request}</span><span className="request-list-footer"><time>{index === 0 ? "Сегодня, 10:24" : `${index + 21} сентября`}</time><span className={`status-chip ${index === 0 ? "status-new" : ""}`}>{index === 0 ? "Новый" : index === 2 ? "В работе" : "Открыт"}</span><b>{index === 0 ? "₸ 942 500" : `₸ ${(index + 3) * 140} 000`}</b></span><ChevronRight className="list-next" size={16} /></button>)}</div><div className="list-count">Показано 8 из 12 заявок <button>Все заявки <ArrowRight size={14} /></button></div></div><main className="quote-workspace"><div className="workspace-crumb"><Link to="/">TenderMarket</Link><ChevronRight size={14} /><span>Мои подходящие заявки</span><span className="crumb-spacer" /><span className={`status-chip ${status === "Предложение отправлено" ? "status-sent" : ""}`}><span />{status}</span></div><div className="workspace-title-row"><div><div className="workspace-kicker"><Link to="/supplier/inbox"><ArrowLeft size={15} />К списку</Link><span>Запрос № TM-2026-0424-{String(selectedRequest + 1).padStart(3, "0")}</span></div><h1>{requests[selectedRequest]}</h1><p>Нужна комплексная поставка товаров для офиса. Возможны аналоги с похожими характеристиками.</p><div className="request-meta"><span><Building2 size={15} />ТОО «Альтаир»</span><span><MapPin size={15} />г. Алматы</span><span><Clock3 size={15} />Ответить до 30 апреля</span></div></div><button className="button button-secondary"><Bookmark size={16} />Сохранить</button></div><div className="quote-deadline"><div className="deadline-icon"><Clock3 size={18} /></div><span><strong>Осталось 6 дней</strong><small>Заказчик принимает предложения до 30 апреля</small></span><span className="deadline-bar"><i /></span></div><div className="quote-table-head"><div><h2>Товары в заявке <span>({quoteItems.length})</span></h2><span>Заполните цену и наличие по каждой позиции</span></div><label className="switch-row"><input type="checkbox" checked={coverageOnly} onChange={event => setCoverageOnly(event.target.checked)} /><span className="switch-track" /><span>Могу поставить все позиции</span></label><span className="coverage-badge"><CheckCircle2 size={16} />Полное покрытие</span></div><div className="quote-table-wrap"><table className="quote-table"><thead><tr><th>№</th><th>Товар и категория</th><th>Количество</th><th>Ваша цена, ₸</th><th>Наличие</th><th>Сумма, ₸</th></tr></thead><tbody>{quoteItems.map((item, index) => <tr key={item.id}><td className="row-number">{String(index + 1).padStart(2, "0")}</td><td><div className="quote-item"><div className="quote-thumb"><img src={item.image} alt="" /></div><span><strong>{item.name}</strong><small>{item.detail}</small><em>{item.category}</em></span></div></td><td className="qty-cell">{item.qty} <span>{item.unit}</span></td><td><label className="price-input-wrap"><input aria-label={`Цена: ${item.name}`} type="number" min="0" value={prices[index]} onChange={event => setPrices(current => current.map((price, i) => i === index ? event.target.value : price))} /><span>₸</span></label></td><td><span className="availability"><Check size={12} />В наличии</span></td><td className="sum-cell">{money(item.qty * (Number(prices[index]) || 0))}</td></tr>)}</tbody></table></div><div className="quote-bottom-grid"><section className="quote-terms"><h3><Truck size={17} />Условия поставки</h3><div className="terms-fields"><label><span>Доставка, ₸</span><input value={delivery} type="number" min="0" onChange={event => setDelivery(event.target.value)} /></label><label><span>Ожидаемая дата</span><input type="date" defaultValue="2026-05-15" /></label></div></section><section className="quote-files"><h3><Paperclip size={17} />Файлы к предложению</h3><p>Коммерческое предложение, каталог или сертификаты</p><label className="file-upload"><input type="file" multiple accept="image/*,video/*,.pdf,.doc,.docx,.xls,.xlsx" onChange={event => setFiles(current => [...current, ...Array.from(event.target.files ?? []).map(file => file.name)])} /><Plus size={15} />Добавить файлы</label>{files.length > 0 && <span className="attached-files"><FileText size={14} />{files.join(", ")}</span>}</section><section className="quote-total"><span>Товары</span><b>{money(total - (Number(delivery) || 0))}</b><span>Доставка</span><b>{money(Number(delivery) || 0)}</b><div className="total-divider" /><span>Общая сумма</span><strong>{money(total)}</strong></section></div><div className="quote-submit-row"><span><ShieldCheck size={16} />Цена и условия будут видны только заказчику</span><div><button className="button button-secondary" onClick={saveDraft}>Сохранить черновик</button><button className="button button-primary" onClick={sendOffer} disabled={!coverageOnly && !prices.some(price => Number(price) > 0)}><Send size={15} />Отправить предложение</button></div></div></main></div>{toast && <div className="toast-message"><CheckCircle2 size={18} />{toast}</div>}</div>;
}

type InboxItem = { id: string; name: string; details: string | null; quantity: string | number; unit: string; categoryId: string | null; category?: { name: string } | null };
type InboxRequest = { id: string; number: number; title: string; description: string | null; region: string; responseDeadline: string | null; items: InboxItem[]; attachments?: Array<{ id: string; originalName: string }>; _count?: { offers: number } };
type ApiCategory = { id: string; slug: string; name: string };
type SupplierSummary = { profile: { publicName: string; isPublished: boolean } | null; publishedProducts: number; openOffers: number; activeDeals: number; campaigns: number };

function SupplierWorkspaceLive() {
  const isAuthenticated = Boolean(readLocal("tm_access_token", ""));
  const [requests, setRequests] = useState<InboxRequest[]>([]);
  const [summary, setSummary] = useState<SupplierSummary | null>(null);
  const [categoriesList, setCategoriesList] = useState<ApiCategory[]>([]);
  const [selectedRequest, setSelectedRequest] = useState(0);
  const [prices, setPrices] = useState<Record<string, string>>({});
  const [delivery, setDelivery] = useState("0");
  const [deliveryDate, setDeliveryDate] = useState("");
  const [coverageOnly, setCoverageOnly] = useState(true);
  const [offerFiles, setOfferFiles] = useState<Array<{ id: string; originalName: string }>>([]);
  const [profileName, setProfileName] = useState("");
  const [selectedCategories, setSelectedCategories] = useState<string[]>([]);
  const [regions, setRegions] = useState<string[]>(() => [readLocal("tm_city", "Алматы")]);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const activeRequest = requests[selectedRequest];
  const amount = (activeRequest?.items ?? []).reduce((sum, item) => sum + Number(item.quantity) * (Number(prices[item.id]) || 0), 0);
  const total = amount + (Number(delivery) || 0);

  useEffect(() => {
    if (!isAuthenticated) { setLoading(false); return; }
    Promise.all([apiRequest<InboxRequest[]>("/supplier/requests"), apiRequest<ApiCategory[]>("/categories"), apiRequest<SupplierSummary>("/supplier/summary")])
      .then(([inbox, allCategories, dashboard]) => { setRequests(inbox); setCategoriesList(allCategories); setSummary(dashboard); if (dashboard.profile) setProfileName(dashboard.profile.publicName); })
      .catch(error => setMessage(error instanceof Error ? error.message : "Не удалось загрузить заявки."))
      .finally(() => setLoading(false));
  }, [isAuthenticated]);

  const toggleCategory = (id: string) => setSelectedCategories(current => current.includes(id) ? current.filter(item => item !== id) : [...current, id]);
  const toggleRegion = (region: string) => setRegions(current => region === "Весь Казахстан" ? current.includes(region) ? [] : [region] : current.includes(region) ? current.filter(item => item !== region) : [...current.filter(item => item !== "Весь Казахстан"), region]);
  const publishProfile = async () => {
    if (!profileName.trim() || !selectedCategories.length || !regions.length) { setMessage("Укажите название витрины, категории и регионы доставки."); return; }
    setSaving(true); setMessage("");
    try {
      await apiRequest("/supplier/profile", { method: "POST", body: JSON.stringify({ publicName: profileName, regions, categoryIds: selectedCategories }) });
      const inbox = await apiRequest<InboxRequest[]>("/supplier/requests");
      setRequests(inbox); setMessage("Витрина опубликована. Подходящие заявки обновлены.");
    } catch (error) { setMessage(error instanceof Error ? error.message : "Не удалось сохранить витрину."); }
    finally { setSaving(false); }
  };
  const uploadOfferFiles = async (files: FileList | null) => {
    if (!files?.length) return;
    try { const uploaded = await Promise.all(Array.from(files).map(file => apiUpload<{ id: string; originalName: string }>(file))); setOfferFiles(current => [...current, ...uploaded]); setMessage(""); }
    catch (error) { setMessage(error instanceof Error ? error.message : "Не удалось загрузить вложения."); }
  };

  const submitOffer = async () => {
    if (!activeRequest) return;
    const rows = activeRequest.items.filter(item => coverageOnly || Number(prices[item.id]) > 0);
    if (!rows.length || (coverageOnly && rows.some(item => Number(prices[item.id]) <= 0))) { setMessage("Укажите цену для каждой позиции предложения."); return; }
    setSaving(true); setMessage("");
    try {
      await apiRequest(`/requests/${activeRequest.id}/offers`, { method: "POST", body: JSON.stringify({ deliveryPrice: Number(delivery), deliveryDate: deliveryDate || undefined, attachments: offerFiles.map(file => file.id), items: rows.map(item => ({ requestItemId: item.id, unitPrice: Number(prices[item.id]), available: true })) }) });
      setMessage("Предложение отправлено заказчику.");
    } catch (error) { setMessage(error instanceof Error ? error.message : "Не удалось отправить предложение."); }
    finally { setSaving(false); }
  };

  return <div className="portal-shell"><PortalHeader title="Подходящие заявки" role="Поставщик" /><div className="portal-layout"><PortalSidebar active="Мои предложения" />{!isAuthenticated ? <main className="supplier-empty"><span className="section-eyebrow">Кабинет поставщика</span><h1>Войдите, чтобы увидеть заявки</h1><p>После регистрации настройте категории и регионы поставки. В ленте появятся подходящие заявки.</p><Link to="/auth" className="button button-primary">Войти или зарегистрироваться <ArrowRight size={16} /></Link></main> : loading ? <main className="supplier-empty">Загружаем подходящие заявки…</main> : requests.length === 0 && summary?.profile?.isPublished ? <main className="supplier-empty"><span className="section-eyebrow">Кабинет поставщика</span><h1>Подходящих заявок пока нет</h1><p>Витрина уже опубликована. Когда появятся заявки по вашим категориям и регионам, они отобразятся здесь.</p><div className="supplier-empty-stats"><span><strong>{summary.publishedProducts}</strong> товаров</span><span><strong>{summary.openOffers}</strong> предложений</span><span><strong>{summary.activeDeals}</strong> активных сделок</span><span><strong>{summary.campaigns}</strong> кампаний</span></div><div className="supplier-empty-actions"><Link className="button button-secondary" to="/supplier/products">Управлять товарами</Link><Link className="button button-primary" to="/supplier/ads">Продвижение витрины</Link></div></main> : requests.length === 0 ? <main className="supplier-empty"><span className="section-eyebrow">Профиль поставщика</span><h1>Настройте свою витрину</h1><p>Выберите категории товаров и регионы доставки. Это определит, какие заявки появятся в вашем кабинете.</p><label className="supplier-setup-name"><span>Название компании или витрины</span><input value={profileName} onChange={event => setProfileName(event.target.value)} placeholder="Например, TechnoPlus" /></label><h2>Категории</h2><div className="supplier-setup-options">{categoriesList.map(category => <label key={category.id}><input type="checkbox" checked={selectedCategories.includes(category.id)} onChange={() => toggleCategory(category.id)} /><span>{category.name}</span></label>)}</div><h2>Регионы доставки</h2><div className="supplier-setup-options">{["Весь Казахстан", ...kazakhstanCities].map(region => <label key={region}><input type="checkbox" checked={regions.includes(region)} onChange={() => toggleRegion(region)} /><span>{region}</span></label>)}</div>{message && <div className="inline-notice">{message}</div>}<button className="button button-primary" onClick={publishProfile} disabled={saving}>{saving ? "Сохраняем…" : "Опубликовать витрину"}<ArrowRight size={16} /></button></main> : <><section className="request-list-panel"><div className="request-list-head"><div><h2>Подходящие заявки</h2><span>По выбранным категориям и регионам</span></div><span className="pill pill-blue">{requests.length} новых</span></div><div className="request-list">{requests.map((request, index) => <button key={request.id} className={`request-list-item ${selectedRequest === index ? "selected" : ""}`} onClick={() => { setSelectedRequest(index); setPrices({}); setMessage(""); }}><span className="request-list-title">{request.title}</span><span className="request-list-footer"><time>{new Intl.DateTimeFormat("ru-KZ", { day: "numeric", month: "short" }).format(new Date(request.responseDeadline ?? Date.now()))}</time><span className="status-chip status-new">Новая</span><b>{request.items.length} поз.</b></span><ChevronRight className="list-next" size={16} /></button>)}</div></section><main className="quote-workspace"><div className="workspace-crumb"><Link to="/">TenderMarket</Link><ChevronRight size={14} /><span>Подходящие заявки</span><span className="crumb-spacer" /><span className="coverage-badge"><CheckCircle2 size={15} />Подбор по профилю</span></div><div className="workspace-title-row"><div><div className="workspace-kicker"><span>Заявка № TM-{activeRequest.number}</span><span>{activeRequest.region}</span></div><h1>{activeRequest.title}</h1><p>{activeRequest.description || "Составьте предложение по позициям заявки и укажите условия поставки."}</p>{activeRequest.attachments?.length ? <div className="request-attachments">{activeRequest.attachments.map(file => <button className="file-pill file-download" key={file.id} onClick={() => void apiDownload(file.id, file.originalName)}><Paperclip size={13} />{file.originalName}</button>)}</div> : null}<div className="request-meta"><span><MapPin size={15} />{activeRequest.region}</span><span><ListChecks size={15} />{activeRequest.items.length} товарных позиций</span></div></div></div><div className="quote-table-head"><div><h2>Товары в заявке <span>({activeRequest.items.length})</span></h2><span>Цена указывается за единицу товара</span></div><label className="switch-row"><input type="checkbox" checked={coverageOnly} onChange={event => setCoverageOnly(event.target.checked)} /><span className="switch-track" /><span>Предложить весь список</span></label></div><div className="quote-table-wrap"><table className="quote-table"><thead><tr><th>№</th><th>Товар и категория</th><th>Количество</th><th>Ваша цена, ₸</th><th>Сумма, ₸</th></tr></thead><tbody>{activeRequest.items.map((item, index) => <tr key={item.id}><td className="row-number">{String(index + 1).padStart(2, "0")}</td><td><div className="quote-item"><span><strong>{item.name}</strong><small>{item.details}</small><em>{item.category?.name ?? categoriesList.find(category => category.id === item.categoryId)?.name ?? "Категория не указана"}</em></span></div></td><td className="qty-cell">{item.quantity} <span>{item.unit}</span></td><td><label className="price-input-wrap"><input aria-label={`Цена: ${item.name}`} type="number" min="0" value={prices[item.id] ?? ""} onChange={event => setPrices(current => ({ ...current, [item.id]: event.target.value }))} placeholder="0" /><span>₸</span></label></td><td className="sum-cell">{money(Number(item.quantity) * (Number(prices[item.id]) || 0))}</td></tr>)}</tbody></table></div><div className="quote-bottom-grid"><section className="quote-terms"><h3><Truck size={17} />Условия поставки</h3><div className="terms-fields"><label><span>Доставка, ₸</span><input value={delivery} type="number" min="0" onChange={event => setDelivery(event.target.value)} /></label><label><span>Ожидаемая дата</span><input type="date" value={deliveryDate} onChange={event => setDeliveryDate(event.target.value)} /></label></div></section><section className="quote-files"><h3><Paperclip size={17} />Файлы к предложению</h3><label className="file-upload"><input type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx" onChange={event => void uploadOfferFiles(event.target.files)} /><Paperclip size={15} />Фото, видео и документы до 50 МБ</label>{offerFiles.map(file => <span key={file.id} className="file-pill"><FileText size={14} />{file.originalName}</span>)}</section><section className="quote-total"><span>Товары</span><b>{money(amount)}</b><span>Доставка</span><b>{money(Number(delivery) || 0)}</b><div className="total-divider" /><span>Общая сумма</span><strong>{money(total)}</strong></section></div>{message && <div className="inline-notice" role="status">{message}</div>}<div className="quote-submit-row"><span><ShieldCheck size={16} />Предложение увидит заказчик заявки</span><button className="button button-primary" onClick={submitOffer} disabled={saving || (coverageOnly && activeRequest.items.some(item => Number(prices[item.id]) <= 0))}>{saving ? "Отправляем…" : "Отправить предложение"}<Send size={15} /></button></div></main></>}</div></div>;
}

type SupplierProductRow = { id: string; name: string; type?: "PRODUCT" | "SERVICE"; description: string | null; price: string | number | null; unit: string; region: string | null; isPublished: boolean; categoryId: string; category: { name: string } };

function SupplierProductsPage() {
  const [rows, setRows] = useState<SupplierProductRow[]>([]);
  const [categoryRows, setCategoryRows] = useState<ApiCategory[]>([]);
  const [itemType, setItemType] = useState<"PRODUCT" | "SERVICE">("PRODUCT");
  const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [price, setPrice] = useState(""); const [categoryId, setCategoryId] = useState(""); const [unit, setUnit] = useState("шт."); const [region, setRegion] = useState(readLocal("tm_city", "Алматы"));
  const [message, setMessage] = useState(""); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false);
  const load = () => Promise.all([apiRequest<SupplierProductRow[]>("/supplier/products"), apiRequest<ApiCategory[]>("/categories")]).then(([items, cats]) => { setRows(items); setCategoryRows(cats); if (!categoryId && cats[0]) setCategoryId(cats[0].id); }).catch(error => setMessage(error instanceof Error ? error.message : "Не удалось загрузить витрину." )).finally(() => setLoading(false));
  useEffect(() => { if (!readLocal("tm_access_token", "")) { setLoading(false); return; } void load(); }, []);
  const addProduct = async (event: FormEvent) => { event.preventDefault(); setSaving(true); setMessage(""); try { await apiRequest("/supplier/products", { method: "POST", body: JSON.stringify({ name, type: itemType, description, price: price ? Number(price) : undefined, categoryId, unit, region, isPublished: true }) }); setName(""); setDescription(""); setPrice(""); await load(); setMessage(`${itemType === "SERVICE" ? "Услуга добавлена" : "Товар добавлен"} в каталог.`); } catch (error) { setMessage(error instanceof Error ? error.message : "Не удалось сохранить позицию."); } finally { setSaving(false); } };
  const togglePublished = async (product: SupplierProductRow) => { try { await apiRequest(`/supplier/products/${product.id}`, { method: "PATCH", body: JSON.stringify({ name: product.name, description: product.description, price: product.price ? Number(product.price) : undefined, categoryId: product.categoryId, unit: product.unit, region: product.region, isPublished: !product.isPublished }) }); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : "Не удалось обновить товар."); } };
  const remove = async (id: string) => { try { await apiRequest(`/supplier/products/${id}`, { method: "DELETE" }); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : "Не удалось удалить товар."); } };
  return <div className="portal-shell"><PortalHeader title="Мои товары и услуги" role="Поставщик" /><div className="portal-layout"><PortalSidebar active="Мои товары" /><main className="admin-main supplier-manage-page"><div className="customer-welcome"><div><span className="section-eyebrow">Витрина поставщика</span><h1>Товары, услуги и цены</h1><p>Опубликованные позиции появляются в общем каталоге и доступны для поиска.</p></div><Link to="/supplier/inbox" className="button button-secondary">К заявкам</Link></div><div className="supplier-manage-grid"><form className="admin-panel manage-form" onSubmit={addProduct}><h2>{itemType === "SERVICE" ? "Добавить услугу / работу" : "Добавить товар"}</h2><label><span>Тип позиции</span><select value={itemType} onChange={e => { const val = e.target.value as "PRODUCT" | "SERVICE"; setItemType(val); if (val === "SERVICE" && unit === "шт.") setUnit("усл."); if (val === "PRODUCT" && unit === "усл.") setUnit("шт."); }}><option value="PRODUCT">Товар</option><option value="SERVICE">Услуга / работа</option></select></label><label><span>{itemType === "SERVICE" ? "Наименование услуги" : "Название товара"}</span><input value={name} onChange={event => setName(event.target.value)} minLength={2} required placeholder={itemType === "SERVICE" ? "Например, монтажные работы или аудит" : "Например, ноутбук 14″"} /></label><label><span>Категория</span><select value={categoryId} onChange={event => setCategoryId(event.target.value)} required>{categoryRows.map(category => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label><label><span>Описание</span><textarea value={description} onChange={event => setDescription(event.target.value)} placeholder="Характеристики, условия, варианты, допуски" /></label><div className="manage-form-row"><label><span>Цена, ₸</span><input type="number" min="0" value={price} onChange={event => setPrice(event.target.value)} placeholder="По запросу" /></label><label><span>Единица</span><input value={unit} onChange={event => setUnit(event.target.value)} /></label></div><label><span>Город оказания / поставки</span><select value={region} onChange={event => setRegion(event.target.value)}><option value="Весь Казахстан">Весь Казахстан</option>{kazakhstanCities.map(city => <option key={city}>{city}</option>)}</select></label><button className="button button-primary" disabled={saving || !categoryId}>{saving ? "Сохраняем…" : itemType === "SERVICE" ? "Опубликовать услугу" : "Опубликовать товар"}</button></form><section className="admin-panel supplier-product-panel"><div className="dashboard-section-head"><h2>Моя витрина</h2><span>{rows.length} позиций</span></div>{loading ? <div className="empty-state">Загружаем позиции…</div> : rows.length ? <div className="supplier-product-list">{rows.map(product => <article key={product.id}><div><div style={{ display: "flex", alignItems: "center", gap: "8px" }}><strong>{product.name}</strong><span className={`item-type-pill ${product.type === "SERVICE" ? "type-service" : "type-product"}`}>{product.type === "SERVICE" ? "Услуга" : "Товар"}</span></div><small>{product.category.name} · {product.region || "Все регионы"}</small></div><b>{product.price ? money(Number(product.price)) : "Цена по запросу"}</b><label className="manage-publish"><input type="checkbox" checked={product.isPublished} onChange={() => void togglePublished(product)} />В каталоге</label><button className="icon-button" aria-label={`Удалить ${product.name}`} onClick={() => void remove(product.id)}><X size={16} /></button></article>)}</div> : <div className="empty-state">Добавьте первую позицию, чтобы наполнить витрину.</div>}</section></div>{message && <div className="inline-notice" role="status">{message}</div>}</main></div></div>;
}

function SupplierAdsPage() {
  const [rows, setRows] = useState<Array<{ id: string; title: string; placement: string; status: string; paymentStatus: string; budget: string | number; startsAt: string; endsAt: string }>>([]);
  const [name, setName] = useState(""); const [budget, setBudget] = useState(""); const [start, setStart] = useState(""); const [end, setEnd] = useState(""); const [message, setMessage] = useState(""); const [loading, setLoading] = useState(true);
  const load = () => apiRequest<typeof rows>("/supplier/advertisements").then(setRows).catch(error => setMessage(error instanceof Error ? error.message : "Не удалось загрузить кампании.")).finally(() => setLoading(false));
  useEffect(() => { if (readLocal("tm_access_token", "")) void load(); else setLoading(false); }, []);
  const submit = async (event: FormEvent) => { event.preventDefault(); setMessage(""); try { await apiRequest("/supplier/advertisements", { method: "POST", body: JSON.stringify({ title: name, placement: "CATEGORY_TOP", budget: Number(budget), startsAt: new Date(start).toISOString(), endsAt: new Date(end).toISOString(), region: readLocal("tm_city", "Алматы") }) }); setName(""); setBudget(""); await load(); setMessage("Кампания отправлена на проверку. Оплату и запуск подтвердит администратор."); } catch (error) { setMessage(error instanceof Error ? error.message : "Не удалось создать кампанию."); } };
  return <div className="portal-shell"><PortalHeader title="Реклама" role="Поставщик" /><div className="portal-layout"><PortalSidebar active="Реклама" /><main className="admin-main supplier-manage-page"><div className="customer-welcome"><div><span className="section-eyebrow">Продвижение витрины</span><h1>Рекламные кампании</h1><p>Заявки на размещение проверяются администратором и явно помечаются рекламой.</p></div></div><div className="supplier-manage-grid"><form className="admin-panel manage-form" onSubmit={submit}><h2>Новая кампания</h2><label><span>Название</span><input value={name} onChange={event => setName(event.target.value)} required minLength={2} placeholder="Продвижение сезонной коллекции" /></label><label><span>Бюджет, ₸</span><input type="number" min="0" required value={budget} onChange={event => setBudget(event.target.value)} /></label><div className="manage-form-row"><label><span>Начало</span><input type="date" required value={start} onChange={event => setStart(event.target.value)} /></label><label><span>Окончание</span><input type="date" required value={end} onChange={event => setEnd(event.target.value)} /></label></div><button className="button button-primary">Отправить на модерацию</button></form><section className="admin-panel supplier-product-panel"><div className="dashboard-section-head"><h2>Мои кампании</h2><span>{rows.length} всего</span></div>{loading ? <div className="empty-state">Загружаем кампании…</div> : rows.length ? <div className="supplier-product-list">{rows.map(ad => <article key={ad.id}><div><strong>{ad.title}</strong><small>{new Intl.DateTimeFormat("ru-KZ", { dateStyle: "medium" }).format(new Date(ad.startsAt))} — {new Intl.DateTimeFormat("ru-KZ", { dateStyle: "medium" }).format(new Date(ad.endsAt))}</small></div><b>{money(Number(ad.budget))}</b><span className="status-chip status-work">{ad.status === "ACTIVE" ? "Активна" : ad.status === "REJECTED" ? "Отклонена" : "На проверке"}</span><small>Оплата: {ad.paymentStatus === "PAID" ? "получена" : "ожидается"}</small></article>)}</div> : <div className="empty-state">Кампаний пока нет.</div>}</section></div>{message && <div className="inline-notice" role="status">{message}</div>}</main></div></div>;
}

function NewRequestPage() {
  const [toast, setToast] = useState("");
  const navigate = useNavigate();
  return <><SiteHeader /><main className="page-wrap new-request-page"><div className="breadcrumbs"><Link to="/">Главная</Link><ChevronRight size={14} /><span>Новая заявка</span></div><div className="new-request-layout"><div><div className="section-eyebrow">Для заказчиков</div><h1>Получите предложения<br />на ваши товары</h1><p>Добавьте все позиции в один список. Поставщики укажут цены по каждой из них.</p><div className="request-benefit"><CheckCircle2 size={18} /><span><strong>Без лишних звонков</strong><small>Поставщики с подходящим ассортиментом ответят в кабинете.</small></span></div><div className="request-benefit"><CheckCircle2 size={18} /><span><strong>Всё прозрачно</strong><small>Сравните наличие, цену, доставку и сроки.</small></span></div><div className="request-benefit"><MessageCircle size={18} /><span><strong>Обсудите детали</strong><small>Выберите поставщика и продолжите в защищённом чате.</small></span></div><img className="request-decoration" src="/products/grocery-set.png" alt="" /></div><section className="request-page-form"><RequestDialog open onClose={() => navigate("/")} onDone={(message, requestId) => { setToast(message); window.setTimeout(() => navigate(`/customer?created=${encodeURIComponent(requestId)}`), 650); }} /></section></div></main><Footer />{toast && <div className="toast-message"><CheckCircle2 size={18} />{toast}</div>}</>;
}

function CustomerDashboard() {
  const [requests, setRequests] = useState<Array<{ id: string; title: string; createdAt: string; items: unknown[]; region: string; _count?: { offers: number } }>>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [deals, setDeals] = useState<Array<{ id: string; number: number; stage: string; agreedTotal: string; offer: { request: { title: string; region: string }; supplier: { name: string } } }>>([]);
  const [params] = useSearchParams();
  const createdId = params.get("created");
  const hasSession = Boolean(readLocal("tm_access_token", ""));
  useEffect(() => {
    if (!hasSession) { setLoading(false); return; }
    Promise.all([apiRequest<typeof requests>("/requests/mine"), apiRequest<typeof deals>("/deals/mine")]).then(([loadedRequests, loadedDeals]) => { setRequests(loadedRequests); setDeals(loadedDeals); }).catch(cause => setError(cause instanceof Error ? cause.message : "Не удалось загрузить данные кабинета.")).finally(() => setLoading(false));
  }, [hasSession]);
  const offersCount = requests.reduce((sum, request) => sum + (request._count?.offers ?? 0), 0);
  return <div className="portal-shell"><PortalHeader title="Мои закупки" role="Заказчик" /><div className="portal-layout customer-layout"><PortalSidebar active="Мои запросы" /><main className="customer-main"><div className="breadcrumbs"><Link to="/">Главная</Link><ChevronRight size={14} /><span>Мои закупки</span></div><div className="customer-welcome"><div><span className="section-eyebrow">Рабочее пространство</span><h1>Мои закупки</h1><p>Здесь собраны ваши заявки, предложения и сделки.</p></div><Link to="/request/new" className="button button-primary"><Plus size={16} />Новая заявка</Link></div>{createdId && <div className="inline-notice success-notice"><CheckCircle2 size={17} />Заявка опубликована. Подходящие поставщики выбранных категорий уже получили уведомление.</div>}{!hasSession ? <div className="empty-state"><UserRound size={23} /><strong>Войдите, чтобы увидеть свои заявки</strong><span>После входа здесь появятся ваши заявки, предложения и сделки.</span><Link className="button button-primary" to="/auth">Войти в аккаунт</Link></div> : <><div className="dashboard-stats"><div><span className="stat-icon blue"><FileText size={18} /></span><span><strong>{requests.length}</strong><small>Всего заявок</small></span></div><div><span className="stat-icon violet"><Send size={18} /></span><span><strong>{offersCount}</strong><small>Предложений</small></span></div><div><span className="stat-icon mint"><BriefcaseBusiness size={18} /></span><span><strong>{deals.length}</strong><small>Сделок</small></span></div></div><div className="dashboard-section-head"><h2>Мои заявки</h2><span>{requests.length} всего</span></div>{loading ? <div className="empty-state">Загружаем ваши заявки…</div> : error ? <div className="empty-state"><strong>Не удалось загрузить заявки</strong><span>{error}</span><button className="button button-secondary" onClick={() => window.location.reload()}>Повторить</button></div> : requests.length ? <div className="customer-request-list">{requests.map(request => <article className={`customer-request ${request.id === createdId ? "request-created-highlight" : ""}`} key={request.id}><div className="customer-request-icon"><ListChecks size={20} /></div><div className="customer-request-copy"><strong>{request.title}</strong><span>{request.items.length} поз. <i /> {request.region} <i /> Опубликована {new Intl.DateTimeFormat("ru", { day: "numeric", month: "long" }).format(new Date(request.createdAt))}</span></div><span className={`status-chip ${request._count?.offers ? "status-new" : "status-work"}`}>{request._count?.offers ? "Есть предложения" : "Ждёт поставщиков"}</span><b>{request._count?.offers ?? 0} предложений</b><Link to={`/requests/${request.id}/offers`} aria-label="Открыть предложения"><ChevronRight size={17} /></Link></article>)}</div> : <div className="empty-state"><FileText size={23} /><strong>Заявок пока нет</strong><span>Опишите список товаров — поставщики пришлют цены и сроки.</span><Link className="button button-primary" to="/request/new"><Plus size={16} />Создать заявку</Link></div>}<div className="dashboard-section-head dashboard-subsection"><h2>История сделок</h2><span>{deals.length} всего</span></div>{deals.length ? <div className="customer-request-list">{deals.map(deal => <article className="customer-request" key={deal.id}><div className="customer-request-icon"><BriefcaseBusiness size={18} /></div><div className="customer-request-copy"><strong>{deal.offer.request.title}</strong><span>TM-{deal.number} · {deal.offer.request.region} · {deal.offer.supplier.name}</span></div><span className="status-chip status-work">{deal.stage}</span><b>{money(Number(deal.agreedTotal))}</b><Link to={`/deals/${deal.id}`} aria-label="Открыть сделку"><ChevronRight size={17} /></Link></article>)}</div> : !loading && <div className="empty-state compact-empty">Завершённые и текущие сделки появятся здесь.</div>}</>}</main></div></div>;
}

type ComparisonOffer = { id: string; status: string; totalPrice: number | string; deliveryPrice: number | string; deliveryDate: string | null; fullCoverage: boolean; attachments?: Array<{ id: string; originalName: string; mimeType: string; sizeBytes: number }>; supplier: { id: string; name: string; supplierProfile?: { averageRating: number; reviewCount: number } | null }; items: Array<{ id: string; requestItemId: string; unitPrice: number | string | null; available: boolean; requestItem: { id: string; name: string; details: string | null; quantity: number | string; unit: string; categoryId: string | null } }> };
type ComparisonRequest = { id: string; title: string; number: number; region: string; items: Array<{ id: string; name: string; details: string | null; quantity: number | string; unit: string; categoryId: string | null }> };

function OfferComparisonLive() {
  const { id = "demo" } = useParams();
  const navigate = useNavigate();
  const isDemo = id === "demo";
  const [offers, setOffers] = useState<ComparisonOffer[]>([]);
  const [request, setRequest] = useState<ComparisonRequest | null>(null);
  const [loading, setLoading] = useState(!isDemo);
  const [error, setError] = useState("");
  useEffect(() => {
    if (isDemo || !readLocal("tm_access_token", "")) { setLoading(false); return; }
    apiRequest<{ request: ComparisonRequest; offers: ComparisonOffer[] }>(`/requests/${id}/offers`).then(result => { setRequest(result.request); setOffers(result.offers); }).catch(cause => setError(cause instanceof Error ? cause.message : "Не удалось загрузить предложения.")).finally(() => setLoading(false));
  }, [id, isDemo]);
  const demoOffers: ComparisonOffer[] = [
    { id: "demo-1", status: "SUBMITTED", totalPrice: 2575000, deliveryPrice: 7500, deliveryDate: "2026-09-28", fullCoverage: true, supplier: { id: "demo-s1", name: "TechnoPlus", supplierProfile: { averageRating: 4.9, reviewCount: 86 } }, items: quoteItems.map(item => ({ id: item.id, requestItemId: item.id, unitPrice: item.price, available: true, requestItem: { id: item.id, name: item.name, details: item.detail, quantity: item.qty, unit: item.unit, categoryId: null } })) },
    { id: "demo-2", status: "SUBMITTED", totalPrice: 2503000, deliveryPrice: 0, deliveryDate: "2026-09-30", fullCoverage: true, supplier: { id: "demo-s2", name: "ОфисМаркет", supplierProfile: { averageRating: 4.8, reviewCount: 57 } }, items: quoteItems.map(item => ({ id: item.id, requestItemId: item.id, unitPrice: item.price * .98, available: true, requestItem: { id: item.id, name: item.name, details: item.detail, quantity: item.qty, unit: item.unit, categoryId: null } })) },
    { id: "demo-3", status: "SUBMITTED", totalPrice: 2544000, deliveryPrice: 10000, deliveryDate: "2026-09-29", fullCoverage: false, supplier: { id: "demo-s3", name: "Barys Trade", supplierProfile: { averageRating: 4.7, reviewCount: 42 } }, items: quoteItems.slice(0, 4).map(item => ({ id: item.id, requestItemId: item.id, unitPrice: item.price * 1.01, available: true, requestItem: { id: item.id, name: item.name, details: item.detail, quantity: item.qty, unit: item.unit, categoryId: null } })) },
  ];
  const displayOffers = isDemo ? demoOffers : offers;
  const items = isDemo ? quoteItems.map(item => ({ id: item.id, name: item.name, details: item.detail, quantity: item.qty, unit: item.unit, image: item.image })) : (request?.items ?? []).map(item => ({ ...item, image: products.find(product => product.name === item.name)?.image ?? "/products/laptop.png" }));
  const choose = async (offer: ComparisonOffer) => {
    if (isDemo) { setError("Это пример интерфейса. Реальная сделка появится после выбора предложения на вашей заявке."); return; }
    try { const deal = await apiRequest<{ id: string }>(`/offers/${offer.id}/accept`, { method: "POST", body: JSON.stringify({}) }); navigate(`/deals/${deal.id}`); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Не удалось выбрать предложение."); }
  };
  return <div className="portal-shell"><PortalHeader title="Сравнение предложений" role="Заказчик" /><div className="portal-layout"><PortalSidebar active="Мои запросы" /><main className="comparison-main"><div className="workspace-kicker"><Link to="/customer"><ArrowLeft size={15} />К моим заявкам</Link><span>{isDemo ? "Пример сравнения" : `Заявка № TM-${request?.number ?? id}`}</span></div><div className="comparison-title"><div><span className="section-eyebrow">{items.length} позиций · {isDemo ? "Алматы" : request?.region ?? "ваш регион"}</span><h1>{isDemo ? "Офисные товары и разные категории" : request?.title ?? "Предложения поставщиков"}</h1><p>Сравните покрытие, построчные цены, сроки поставки и рейтинг.</p></div><span className="coverage-badge"><CheckCircle2 size={16} />Полнота учтена</span></div>{loading ? <div className="empty-state">Загружаем предложения…</div> : !displayOffers.length ? <div className="empty-state"><Package size={22} /><strong>Предложений пока нет</strong><span>Подходящие поставщики увидят заявку и отправят расчёт сюда.</span></div> : <div className="comparison-table-wrap"><table className="comparison-table"><thead><tr><th>Товар в заявке</th>{displayOffers.map(offer => <th key={offer.id}><strong>{offer.supplier.name}</strong><span>{offer.fullCoverage ? "Полное предложение" : `${offer.items.length} из ${items.length} позиций`}</span><small><Star size={13} fill="currentColor" />{offer.supplier.supplierProfile?.averageRating?.toLocaleString("ru-KZ") ?? "—"} · до {offer.deliveryDate ? new Intl.DateTimeFormat("ru-KZ", { day: "numeric", month: "short" }).format(new Date(offer.deliveryDate)) : "срок уточняется"}</small>{offer.attachments?.map(file => <button className="file-pill file-download" key={file.id} onClick={() => void apiDownload(file.id, file.originalName)}><Paperclip size={13} />{file.originalName}</button>)}</th>)}</tr></thead><tbody>{items.map(item => <tr key={item.id}><td><span className="comparison-item"><img src={item.image} alt="" /><span><strong>{item.name}</strong><small>{item.quantity} {item.unit}</small></span></span></td>{displayOffers.map(offer => { const quote = offer.items.find(line => line.requestItemId === item.id); return <td key={offer.id}>{quote?.available ? money(Number(quote.unitPrice) * Number(item.quantity)) : "—"}<span className="line-check">{quote?.available ? <><Check size={12} />В наличии</> : "Нет в предложении"}</span></td>; })}</tr>)}</tbody><tfoot><tr><td>Итог с доставкой</td>{displayOffers.map(offer => <td key={offer.id}><strong>{money(Number(offer.totalPrice))}</strong><button className="button button-primary" onClick={() => choose(offer)}>Выбрать предложение</button></td>)}</tr></tfoot></table></div>}{error && <div className="inline-notice" role="status">{error}</div>}</main></div></div>;
}

function OfferComparisonPage() {
  const [toast, setToast] = useState("");
  const offers = [{ name: "TechnoPlus", total: 2575000, delivery: 7500, date: "28 апреля", rating: "4,9", full: true }, { name: "ОфисМаркет", total: 2503000, delivery: 0, date: "30 апреля", rating: "4,8", full: true }, { name: "Barys Trade", total: 2544000, delivery: 10000, date: "29 апреля", rating: "4,7", full: false }];
  const select = (name: string) => { saveLocal("tm_selected_offer", { name, selectedAt: new Date().toISOString() }); setToast(`Вы выбрали ${name}. Сделка создана, чат доступен в кабинете.`); window.setTimeout(() => setToast(""), 4000); };
  return <div className="portal-shell"><PortalHeader title="Сравнение предложений" role="Заказчик" /><div className="portal-layout"><PortalSidebar active="Мои запросы" /><main className="comparison-main"><div className="workspace-kicker"><Link to="/customer"><ArrowLeft size={15} />К моим заявкам</Link><span>Заявка № TM-2026-0424-001</span></div><div className="comparison-title"><div><span className="section-eyebrow">8 позиций · Алматы</span><h1>Офисные товары и разные категории</h1><p>Предложения сравниваются по наличию, цене и сроку поставки.</p></div><span className="coverage-badge"><CheckCircle2 size={16} />Все позиции учтены</span></div><div className="comparison-table-wrap"><table className="comparison-table"><thead><tr><th>Товар в заявке</th>{offers.map(offer => <th key={offer.name}><strong>{offer.name}</strong><span>{offer.full ? "Полное предложение" : "6 из 8 позиций"}</span><small><Star size={13} fill="currentColor" />{offer.rating} · Доставка {offer.date}</small></th>)}</tr></thead><tbody>{quoteItems.map(item => <tr key={item.id}><td><span className="comparison-item"><img src={item.image} alt="" /><span><strong>{item.name}</strong><small>{item.qty} {item.unit}</small></span></span></td>{offers.map(offer => <td key={offer.name}>{money(item.qty * item.price * (offer.name === "ОфисМаркет" ? 0.98 : offer.name === "Barys Trade" ? 1.01 : 1))}<span className="line-check"><Check size={12} />В наличии</span></td>)}</tr>)}</tbody><tfoot><tr><td>Итог с доставкой</td>{offers.map(offer => <td key={offer.name}><strong>{money(offer.total)}</strong><button className="button button-primary" onClick={() => select(offer.name)}>Выбрать предложение</button></td>)}</tr></tfoot></table></div></main></div>{toast && <div className="toast-message"><CheckCircle2 size={18} />{toast} <Link to="/deals/demo">Открыть сделку</Link></div>}</div>;
}

function DealPage() {
  const [text, setText] = useState("");
  const [messages, setMessages] = useState(() => readLocal<Array<{ id: string; text: string; own: boolean; time: string }>>("tm_demo_messages", [{ id: "m1", text: "Добрый день! Можем поставить весь список до 15 мая. Предложение и сертификаты приложили.", own: false, time: "10:12" }, { id: "m2", text: "Спасибо, уточните, пожалуйста, срок гарантии на ноутбуки.", own: true, time: "10:25" }]));
  const [stage, setStage] = useState(2);
  const send = (event: FormEvent) => { event.preventDefault(); if (!text.trim()) return; const next = [...messages, { id: crypto.randomUUID(), text: text.trim(), own: true, time: new Date().toLocaleTimeString("ru", { hour: "2-digit", minute: "2-digit" }) }]; setMessages(next); saveLocal("tm_demo_messages", next); setText(""); };
  return <div className="portal-shell"><PortalHeader title="Сделка и сообщения" role="Заказчик" notifications={1} /><div className="portal-layout"><PortalSidebar active="Сообщения" /><main className="deal-main"><div className="workspace-kicker"><Link to="/customer"><ArrowLeft size={15} />Назад к закупкам</Link><span>Сделка № TM-2026-0424-001</span><span className="status-chip status-work">В работе</span></div><div className="deal-top"><div><h1>Офисные товары, техника и продукты</h1><p>ТОО «Альтаир» <i /> Поставщик TechnoPlus</p></div><Link to="/requests/demo/offers" className="button button-secondary">Условия сделки <FileText size={15} /></Link></div><div className="deal-progress">{["Согласование", "Подтверждена", "В работе", "Доставлена", "Завершена"].map((label, index) => <button key={label} className={index <= stage ? "done" : ""} onClick={() => setStage(index)}><span>{index < stage ? <Check size={13} /> : index + 1}</span><small>{label}</small></button>)}</div><div className="deal-chat"><div className="chat-header"><span className="supplier-mark blue">T+</span><div><strong>TechnoPlus</strong><small><span className="online-dot" />Поставщик · отвечает быстро</small></div><button className="button button-secondary">Открыть спор</button></div><div className="chat-day">Сегодня, 24 апреля</div><div className="chat-messages">{messages.map(message => <div key={message.id} className={`chat-message ${message.own ? "own" : ""}`}><p>{message.text}</p><time>{message.time}{message.own && <Check size={12} />}</time></div>)}<button className="file-message"><FileText size={17} /><span><strong>Предложение и спецификация.pdf</strong><small>PDF · 1,8 МБ</small></span><ArrowDown size={15} /></button></div><form className="chat-input" onSubmit={send}><button type="button" className="icon-button" aria-label="Добавить файл"><Paperclip size={18} /></button><input value={text} onChange={event => setText(event.target.value)} placeholder="Напишите сообщение…" aria-label="Сообщение" /><button type="submit" className="button button-primary" disabled={!text.trim()}><Send size={15} />Отправить</button></form></div></main></div></div>;
}

type SubcontractBidRecord = {
  id: string;
  price: string | number;
  proposedDate: string | null;
  note: string | null;
  status: string;
  createdAt: string;
  contractor: {
    id: string;
    name: string;
    region: string | null;
    supplierProfile?: { publicName: string; averageRating: number; reviewCount: number } | null;
  };
};

type SubcontractRecord = {
  id: string;
  number: number;
  dealId: string;
  title: string;
  targetRegion: string;
  description: string | null;
  agreedAmount: string | number;
  currency: string;
  deadline: string | null;
  status: "SEARCHING" | "AGREED" | "IN_PROGRESS" | "COMPLETED" | "CANCELLED";
  contractTerms: string | null;
  createdAt: string;
  completedAt: string | null;
  generalSupplier: { id: string; name: string; region: string | null };
  subcontractor?: {
    id: string;
    name: string;
    region: string | null;
    supplierProfile?: { publicName: string; averageRating: number; reviewCount: number } | null;
  } | null;
  bids?: SubcontractBidRecord[];
};

type LocalContractor = {
  id: string;
  name: string;
  region: string | null;
  supplierProfile?: {
    publicName: string;
    about: string | null;
    averageRating: number;
    reviewCount: number;
    deliveryRegions: string[];
    categories: Array<{ category: { id: string; name: string; slug: string } }>;
  } | null;
};

export type DealRecord = { id: string; number: number; stage: string; agreedTotal: string; viewerRole?: string | null; offer: { request: { title: string; number: number; region: string }; supplier: { name: string; region?: string | null } }; subcontracts?: SubcontractRecord[] };
export type DealMessage = { id: string; body: string; authorId: string | null; systemEvent: boolean; createdAt: string; author?: { displayName: string } | null; attachments?: Array<{ id: string; originalName: string; mimeType: string; sizeBytes: number }> };

function DealPageLive() {
  const { id = "demo" } = useParams();
  const isDemo = id === "demo";
  const userId = readLocal("tm_user_id", "");
  const [userRole, setUserRole] = useState(() => readLocal<string>("tm_user_role", ""));
  const [deal, setDeal] = useState<DealRecord | null>(null);
  const [subcontracts, setSubcontracts] = useState<SubcontractRecord[]>([]);
  const [dealLoading, setDealLoading] = useState(!isDemo);
  const [messages, setMessages] = useState<DealMessage[]>(() => readLocal<DealMessage[]>("tm_demo_messages", [{ id: "sample-1", body: "Добрый день! Можем поставить весь список. Предложение и сертификаты приложили.", authorId: null, systemEvent: false, createdAt: new Date().toISOString() }]));
  const [text, setText] = useState("");
  const [error, setError] = useState("");
  const [chatFiles, setChatFiles] = useState<Array<{ id: string; originalName: string }>>([]);
  const [disputeFiles, setDisputeFiles] = useState<Array<{ id: string; originalName: string }>>([]);
  const [disputeOpen, setDisputeOpen] = useState(false);
  const [disputeReason, setDisputeReason] = useState("");
  const [disputeDetails, setDisputeDetails] = useState("");
  const stageLabels = ["Согласование", "Подтверждена", "В работе", "Отправлена", "Получена", "Завершена"];
  const stageValues = ["NEGOTIATION", "CONFIRMED", "IN_PROGRESS", "SHIPPED", "RECEIVED", "COMPLETED"];
  const activeStage = deal ? Math.max(0, stageValues.indexOf(deal.stage)) : isDemo ? 2 : 0;
  useEffect(() => {
    if (isDemo) { setDealLoading(false); return; }
    if (!readLocal("tm_access_token", "")) { setError("Войдите в аккаунт, чтобы открыть сделку."); setDealLoading(false); return; }
    Promise.all([apiRequest<DealRecord>(`/deals/${id}`), apiRequest<DealMessage[]>(`/deals/${id}/messages`)]).then(([loadedDeal, loadedMessages]) => { setDeal(loadedDeal); if (loadedDeal.subcontracts) setSubcontracts(loadedDeal.subcontracts); setMessages(loadedMessages); if (loadedDeal.viewerRole) { setUserRole(loadedDeal.viewerRole); saveLocal("tm_user_role", loadedDeal.viewerRole); } }).catch(error => setError(error instanceof Error ? error.message : "Не удалось загрузить сделку.")).finally(() => setDealLoading(false));
  }, [id, isDemo]);
  const send = async (event: FormEvent) => {
    event.preventDefault(); if (!text.trim()) return;
    if (isDemo) { const next = [...messages, { id: crypto.randomUUID(), body: text.trim(), authorId: userId || "buyer", systemEvent: false, createdAt: new Date().toISOString() }]; setMessages(next); saveLocal("tm_demo_messages", next); setText(""); return; }
    try { const message = await apiRequest<DealMessage>(`/deals/${id}/messages`, { method: "POST", body: JSON.stringify({ body: text.trim(), attachments: chatFiles.map(file => file.id) }) }); setMessages(current => [...current, message]); setChatFiles([]); setText(""); setError(""); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Не удалось отправить сообщение."); }
  };
  const changeStage = async (index: number) => {
    if (index <= activeStage || index > activeStage + 1) return;
    if (isDemo) return;
    try { const updated = await apiRequest<DealRecord>(`/deals/${id}/stage`, { method: "POST", body: JSON.stringify({ stage: stageValues[index] }) }); setDeal(current => current ? { ...current, stage: updated.stage } : current); const latestMessages = await apiRequest<DealMessage[]>(`/deals/${id}/messages`); setMessages(latestMessages); setError(""); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Не удалось обновить этап."); }
  };
  const openDispute = async (event: FormEvent) => {
    event.preventDefault();
    if (isDemo) { setError("Для спора нужна созданная на сервере сделка."); return; }
    try { await apiRequest(`/deals/${id}/disputes`, { method: "POST", body: JSON.stringify({ reason: disputeReason, details: disputeDetails, attachments: disputeFiles.map(file => file.id) }) }); setDisputeOpen(false); setDisputeFiles([]); setError("Спор открыт. Участники получат уведомление."); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Не удалось открыть спор."); }
  };
  const uploadDealFiles = async (files: FileList | null, target: "chat" | "dispute") => {
    if (!files?.length) return;
    try { const uploaded = await Promise.all(Array.from(files).map(file => apiUpload<{ id: string; originalName: string }>(file))); (target === "chat" ? setChatFiles : setDisputeFiles)(current => [...current, ...uploaded]); setError(""); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Не удалось загрузить файл."); }
  };
  const dealTitle = deal?.offer.request.title ?? "Офисные товары, техника и продукты";
  const supplierName = deal?.offer.supplier.name ?? "TechnoPlus";
  const nextStage = activeStage + 1;
  const nextActor = nextStage >= 4 ? "CUSTOMER" : "SUPPLIER";
  const canAdvance = Boolean(deal && userRole === nextActor && nextStage < stageValues.length);
  const nextAction = ["", "Подтвердить условия", "Отметить начало работ", "Отметить отправку", "Подтвердить получение", "Завершить сделку"][nextStage] ?? "";
  if (!isDemo && dealLoading) return <div className="portal-shell"><PortalHeader title="Сделка" role="Участник" /><main className="deal-main"><div className="empty-state">Загружаем сделку…</div></main></div>;
  if (!isDemo && !deal) return <div className="portal-shell"><PortalHeader title="Сделка" role="Участник" /><main className="deal-main"><div className="empty-state"><strong>Не удалось открыть сделку</strong><span>{error || "Проверьте вход в аккаунт и попробуйте снова."}</span><Link className="button button-secondary" to="/customer">Вернуться к закупкам</Link></div></main></div>;
  return <div className="portal-shell"><PortalHeader title="Сделка и сообщения" role="Заказчик" /><div className="portal-layout"><PortalSidebar active="Сообщения" /><main className="deal-main"><div className="workspace-kicker"><Link to="/customer"><ArrowLeft size={15} />Назад к закупкам</Link><span>{deal ? `Сделка № TM-${deal.number}` : "Демонстрационный пример"}</span><span className="status-chip status-work">{stageLabels[activeStage]}</span></div><div className="deal-top"><div><h1>{dealTitle}</h1><p>Заказчик <i /> Поставщик {supplierName}{deal && <span> · {deal.offer.request.region}</span>}</p></div>{deal && <strong>{money(Number(deal.agreedTotal))}</strong>}</div><div className="deal-progress" aria-label="Этапы сделки">{stageLabels.map((label, index) => <div key={label} className={index <= activeStage ? "done" : ""} aria-current={index === activeStage ? "step" : undefined}><span>{index < activeStage ? <Check size={13} /> : index + 1}</span><small>{label}</small></div>)}</div><div className="deal-next-action">{isDemo ? <span>Это пример сделки. В настоящей сделке здесь появится действие для ответственной стороны.</span> : nextStage < stageValues.length ? <><span>{userRole === nextActor ? "Ваш следующий шаг" : `Ожидается действие: ${nextActor === "SUPPLIER" ? "поставщика" : "заказчика"}`}</span>{canAdvance && <button className="button button-primary" onClick={() => changeStage(nextStage)}>{nextAction}<ArrowRight size={15} /></button>}</> : <span>Сделка завершена.</span>}</div>{deal && <DealSubcontractSection deal={deal} subcontracts={subcontracts} setSubcontracts={setSubcontracts} userRole={userRole} isDemo={isDemo} dealId={id} supplierName={supplierName} setMessages={setMessages} />}{deal && <DealDocumentsSection dealId={deal.id} userRole={userRole} isDemo={isDemo} onDocumentSigned={async () => { const latestMessages = await apiRequest<DealMessage[]>(`/deals/${id}/messages`); setMessages(latestMessages); }} />}<div className="deal-chat"><div className="chat-header"><span className="supplier-mark blue">T+</span><div><strong>{supplierName}</strong><small><span className="online-dot" />Поставщик · приватный чат сделки</small></div><button className="button button-secondary" onClick={() => setDisputeOpen(open => !open)}>Открыть спор</button></div>{disputeOpen && <form className="dispute-form" onSubmit={openDispute}><label><span>Причина спора</span><input required minLength={2} value={disputeReason} onChange={event => setDisputeReason(event.target.value)} placeholder="Например, товар не соответствует условиям" /></label><label><span>Опишите ситуацию</span><textarea required minLength={10} value={disputeDetails} onChange={event => setDisputeDetails(event.target.value)} placeholder="Что произошло и какого решения вы ожидаете?" /></label><label className="file-upload"><input type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx" onChange={event => void uploadDealFiles(event.target.files, "dispute")} /><Paperclip size={15} />Приложить доказательства</label>{disputeFiles.map(file => <span className="file-pill" key={file.id}>{file.originalName}</span>)}<button className="button button-primary">Передать арбитру</button></form>}<div className="chat-day">Переписка по сделке</div><div className="chat-messages">{messages.map(message => <div key={message.id} className={`chat-message ${message.authorId === userId && !message.systemEvent ? "own" : ""}`}><p>{message.systemEvent ? <><CheckCircle2 size={14} /> {message.body}</> : message.body}</p><time>{new Intl.DateTimeFormat("ru-KZ", { hour: "2-digit", minute: "2-digit" }).format(new Date(message.createdAt))}</time>{message.attachments?.map(file => <button className="file-pill file-download" key={file.id} onClick={() => void apiDownload(file.id, file.originalName)}><Paperclip size={13} />{file.originalName}</button>)}</div>)}</div><form className="chat-input" onSubmit={send}><label className="icon-button file-icon-upload" aria-label="Добавить файл"><input type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx" onChange={event => void uploadDealFiles(event.target.files, "chat")} /><Paperclip size={18} /></label><input value={text} onChange={event => setText(event.target.value)} placeholder="Напишите сообщение…" aria-label="Сообщение" /><button type="submit" className="button button-primary" disabled={!text.trim()}><Send size={15} />Отправить</button></form></div>{error && <div className="inline-notice" role="status">{error}</div>}</main></div></div>;
}

function ArbiterPage() {
  const [cases, setCases] = useState<any[]>([]); const [decision, setDecision] = useState(""); const [error, setError] = useState(""); const [loading, setLoading] = useState(true);
  const load = () => apiRequest<any[]>("/arbiter/disputes").then(setCases).catch(cause => setError(cause instanceof Error ? cause.message : "Не удалось загрузить назначенные споры.")).finally(() => setLoading(false));
  useEffect(() => { if (readLocal("tm_access_token", "")) void load(); else setLoading(false); }, []);
  const resolve = async (row: any, status: "RESOLVED" | "REJECTED") => { try { await apiRequest(`/arbiter/disputes/${row.id}/decision`, { method: "POST", body: JSON.stringify({ decision, status }) }); setDecision(""); setError("Решение сохранено в журнале."); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Не удалось сохранить решение."); } };
  return <div className="portal-shell"><PortalHeader title="Рабочее место арбитра" role="Арбитр" /><div className="portal-layout"><PortalSidebar active="Арбитраж" /><main className="admin-main"><div className="customer-welcome"><div><span className="section-eyebrow">Только назначенные дела</span><h1>Арбитраж</h1><p>Изучите материалы и историю сделки, затем зафиксируйте мотивированное решение.</p></div></div>{loading ? <div className="empty-state">Загружаем дела…</div> : cases.length ? <div className="admin-case-list">{cases.map(row => <article className="admin-case" key={row.id}><div className="admin-case-head"><div><strong>Спор · TM-{row.deal?.number ?? row.dealId.slice(0, 8)} · {row.deal?.offer?.request?.title ?? "Сделка"}</strong><small>{row.reason} · комиссия {money(Number(row.arbitrationFee))} · {row.feeStatus}</small></div><span className="status-chip status-work">{row.status}</span></div><p>{row.details}</p><div className="arbiter-evidence">{row.deal?.messages?.map((message: any) => <div key={message.id}><p>{message.body}</p>{message.attachments?.map((file: any) => <button className="file-pill file-download" key={file.id} onClick={() => void apiDownload(file.id, file.originalName)}><Paperclip size={14} />{file.originalName}</button>)}</div>)}</div><textarea className="arbiter-decision" value={decision} onChange={event => setDecision(event.target.value)} minLength={10} placeholder="Мотивированное решение: выводы и основание (не менее 10 символов)" /><div className="admin-case-actions"><button className="button button-primary" disabled={decision.trim().length < 10} onClick={() => void resolve(row, "RESOLVED")}>Вынести решение</button><button className="button button-secondary" disabled={decision.trim().length < 10} onClick={() => void resolve(row, "REJECTED")}>Отклонить обращение</button></div></article>)}</div> : <div className="empty-state"><ShieldCheck size={24} /><strong>Назначенных споров нет</strong><span>Новые дела появятся здесь после назначения администратором.</span></div>}{error && <div className="inline-notice" role="status">{error}</div>}</main></div></div>;
}

function AdminPage() {
  const tabs = [{ label: "Обзор", key: "overview", icon: LayoutDashboard }, { label: "Пользователи", key: "users", icon: UserRound }, { label: "Категории", key: "categories", icon: Package }, { label: "Заявки", key: "requests", icon: FileText }, { label: "Сделки", key: "deals", icon: BriefcaseBusiness }, { label: "Субподряды", key: "subcontracts", icon: Handshake }, { label: "Арбитраж", key: "disputes", icon: ShieldCheck }, { label: "Реклама", key: "advertisements", icon: Sparkles }, { label: "Товары", key: "products", icon: Package }, { label: "Отзывы", key: "reviews", icon: Star }, { label: "Аудит", key: "audit", icon: FileText }, { label: "Тарифы", key: "settings", icon: SlidersHorizontal }];
  const [tab, setTab] = useState("overview");
  const [rows, setRows] = useState<any[]>([]);
  const [overview, setOverview] = useState<Record<string, number> | null>(null);
  const [settings, setSettings] = useState<any>({ arbitration: { enabled: false, feeKzt: 0, freeUntil: "" }, advertising: { minimumBudgetKzt: 0, defaultDurationDays: 30 } });
  const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [notice, setNotice] = useState("");
  const [categoryForm, setCategoryForm] = useState({ name: "", slug: "", description: "" }); const [arbiterId, setArbiterId] = useState(""); const [decision, setDecision] = useState("");
  const title = tabs.find(item => item.key === tab)?.label ?? "Обзор";
  const load = async () => {
    setLoading(true); setError("");
    try {
      if (tab === "overview") setOverview(await apiRequest<Record<string, number>>("/admin/overview"));
      else if (tab === "settings") setSettings({ ...settings, ...await apiRequest<any>("/admin/settings/all") });
      else setRows(await apiRequest<any[]>(`/admin/${tab}`));
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Не удалось загрузить данные админки."); }
    finally { setLoading(false); }
  };
  useEffect(() => { if (!readLocal("tm_access_token", "")) { setLoading(false); return; } void load(); }, [tab]);
  const act = async (path: string, method: "POST" | "PATCH", body: unknown) => { setNotice(""); setError(""); try { await apiRequest(path, { method, body: JSON.stringify(body) }); setNotice("Изменения сохранены."); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Не удалось выполнить действие."); } };
  const saveSettings = (key: "arbitration" | "advertising") => void act("/admin/settings", "POST", { key, value: settings[key] });
  const exportRows = () => { const content = JSON.stringify(tab === "overview" ? overview : tab === "settings" ? settings : rows, null, 2); const href = URL.createObjectURL(new Blob([content], { type: "application/json" })); const a = document.createElement("a"); a.href = href; a.download = `tendermarket-${tab}.json`; a.click(); URL.revokeObjectURL(href); };
  const renderRows = () => {
    if (tab === "subcontracts") return <div className="admin-case-list">{rows.map(row => <article className="admin-subcontract-card" key={row.id}><div className="admin-subcontract-head"><div><strong>Субподряд SP-{row.number} · {row.title}</strong><small>г. {row.targetRegion} · Сделка № TM-{row.deal?.number ?? "—"} ({row.deal?.offer?.request?.title ?? "Закупка"})</small></div><span className={`status-chip ${row.status === "COMPLETED" ? "status-success" : row.status === "CANCELLED" ? "status-canceled" : "status-work"}`}>{row.status === "SEARCHING" ? "Поиск исполнителя" : row.status === "AGREED" ? "Исполнитель выбран" : row.status === "IN_PROGRESS" ? "В исполнении" : row.status === "COMPLETED" ? "Выполнен" : "Отменен"}</span></div><div className="admin-subcontract-meta"><div><small>Генподрядчик:</small><strong>{row.generalSupplier?.name} ({row.generalSupplier?.region || "Казахстан"})</strong></div><div><small>Субподрядчик:</small><strong>{row.subcontractor?.name ? `${row.subcontractor.name} (${row.subcontractor.region || ""})` : "Не назначен"}</strong></div><div><small>Сумма:</small><b>{money(Number(row.agreedAmount))}</b></div><div><small>Откликов:</small><span>{row._count?.bids ?? row.bids?.length ?? 0}</span></div></div>{row.bids?.length > 0 && <div className="admin-subcontract-bids"><strong>Отклики локальных подрядчиков:</strong><div style={{ display: "flex", flexWrap: "wrap", gap: "6px", marginTop: "4px" }}>{row.bids.map((bid: any) => <span key={bid.id} className="file-pill">{bid.contractor?.name}: {money(Number(bid.price))} ({bid.status})</span>)}</div></div>}<div className="admin-case-actions">{row.status !== "COMPLETED" && row.status !== "CANCELLED" && <button className="button button-primary" onClick={() => void act(`/admin/subcontracts/${row.id}`, "PATCH", { action: "complete" })}>Завершить</button>}{row.status !== "CANCELLED" && <button className="button button-secondary" onClick={() => void act(`/admin/subcontracts/${row.id}`, "PATCH", { action: "cancel" })}>Отменить</button>}</div></article>)}</div>;
    if (tab === "disputes") return <div className="admin-case-list">{rows.map(row => <article className="admin-case" key={row.id}><div className="admin-case-head"><div><strong>Спор · TM-{row.deal?.number ?? row.dealId.slice(0, 8)} · {row.deal?.offer?.request?.title ?? "Сделка"}</strong><small>{row.reason} · открыт {new Date(row.createdAt).toLocaleDateString("ru-KZ")} · комиссия {money(Number(row.arbitrationFee))} ({row.feeStatus})</small></div><span className="status-chip status-work">{row.status}</span></div><p>{row.details}</p><label className="admin-inline-field"><span>ID арбитра для назначения</span><input value={arbiterId} onChange={event => setArbiterId(event.target.value)} placeholder="ID пользователя с ролью ARBITER" /></label><div className="admin-case-actions"><button className="button button-secondary" onClick={() => void act(`/admin/disputes/${row.id}/assign`, "PATCH", { arbiterId })} disabled={!arbiterId}>Назначить арбитра</button><input value={decision} onChange={event => setDecision(event.target.value)} placeholder="Мотивированное решение, от 10 символов" /><button className="button button-primary" disabled={decision.trim().length < 10} onClick={() => void act(`/admin/disputes/${row.id}/decision`, "POST", { decision, status: "RESOLVED" })}>Решить спор</button><button className="button button-secondary" disabled={decision.trim().length < 10} onClick={() => void act(`/admin/disputes/${row.id}/decision`, "POST", { decision, status: "REJECTED" })}>Отклонить</button></div>{row.deal?.messages?.flatMap((message: any) => message.attachments ?? []).map((file: any) => <button className="file-pill file-download" key={file.id} onClick={() => void apiDownload(file.id, file.originalName)}><Paperclip size={14} />{file.originalName}</button>)}</article>)}</div>;
    if (tab === "advertisements") return <div className="supplier-product-list">{rows.map(row => <article key={row.id}><div><strong>{row.title}</strong><small>{row.organization?.name} · {row.category?.name ?? row.placement} · {row.region ?? "Все регионы"}</small></div><b>{money(Number(row.budget))}</b><span className="status-chip status-work">{row.status} · {row.paymentStatus}</span><button className="button button-secondary" onClick={() => void act(`/admin/advertisements/${row.id}`, "PATCH", { action: "approve" })}>Одобрить</button><button className="button button-secondary" onClick={() => void act(`/admin/advertisements/${row.id}`, "PATCH", { action: "paid" })}>Оплата получена</button><button className="icon-button" aria-label="Отклонить кампанию" onClick={() => void act(`/admin/advertisements/${row.id}`, "PATCH", { action: "reject" })}><X size={16} /></button></article>)}</div>;
    if (tab === "reviews") return <div className="supplier-product-list">{rows.map(row => <article key={row.id}><div><strong>{row.rating} / 5 · {row.author?.displayName} → {row.supplier?.publicName}</strong><small>{row.comment || "Без комментария"} · {new Date(row.createdAt).toLocaleDateString("ru-KZ")}</small></div><span className="status-chip status-work">{row.publishedAt ? "Опубликован" : "Скрыт"}</span><button className="button button-secondary" onClick={() => void act(`/admin/reviews/${row.id}`, "PATCH", { isPublished: !row.publishedAt })}>{row.publishedAt ? "Скрыть отзыв" : "Опубликовать"}</button></article>)}</div>;
    if (tab === "products") return <div className="supplier-product-list">{rows.map(row => <article key={row.id}><div><strong>{row.name}</strong><small>{row.organization?.name} · {row.category?.name} · {row.region ?? "Все города"}</small></div><b>{row.price ? money(Number(row.price)) : "Цена по запросу"}</b><span className="status-chip status-work">{row.isPublished ? "В каталоге" : "Скрыт"}</span><button className="button button-secondary" onClick={() => void act(`/admin/products/${row.id}`, "PATCH", { isPublished: !row.isPublished })}>{row.isPublished ? "Скрыть" : "Опубликовать"}</button></article>)}</div>;
    if (tab === "categories") return <><form className="admin-category-form" onSubmit={event => { event.preventDefault(); void act("/admin/categories", "POST", { ...categoryForm, sortOrder: rows.length }); setCategoryForm({ name: "", slug: "", description: "" }); }}><input required placeholder="Название категории" value={categoryForm.name} onChange={event => setCategoryForm(current => ({ ...current, name: event.target.value }))} /><input required placeholder="slug" value={categoryForm.slug} onChange={event => setCategoryForm(current => ({ ...current, slug: event.target.value }))} /><button className="button button-primary">Добавить</button></form><div className="supplier-product-list">{rows.map(row => <article key={row.id}><div><strong>{row.name}</strong><small>{row.slug} · {row.description}</small></div><span className="status-chip status-work">{row.isActive ? "Активна" : "Скрыта"}</span><button className="button button-secondary" onClick={() => void act(`/admin/categories/${row.id}`, "PATCH", { name: row.name, slug: row.slug, description: row.description, icon: row.icon, sortOrder: row.sortOrder, isActive: !row.isActive })}>{row.isActive ? "Скрыть" : "Опубликовать"}</button></article>)}</div></>;
    if (tab === "users") return <div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Пользователь</th><th>Организация / роль</th><th>Регистрация</th><th>Доступ</th><th></th></tr></thead><tbody>{rows.map(row => <tr key={row.id}><td><strong>{row.displayName}</strong><small>{row.email ?? row.phone}</small></td><td>{row.memberships?.map((m: any) => `${m.organization?.name} · ${m.role}`).join(", ")}</td><td>{new Date(row.createdAt).toLocaleDateString("ru-KZ")}</td><td>{row.isActive ? "Активен" : "Отключён"}</td><td><button className="button button-secondary" onClick={() => void act(`/admin/users/${row.id}`, "PATCH", { isActive: !row.isActive })}>{row.isActive ? "Отключить" : "Включить"}</button></td></tr>)}</tbody></table></div>;
    const fields: Record<string, string[]> = { requests: ["title", "region", "status", "createdAt"], deals: ["number", "stage", "agreedTotal", "updatedAt"], products: ["name", "category", "organization", "price", "isPublished"], reviews: ["rating", "comment", "author", "supplier", "createdAt"], audit: ["action", "entityType", "entityId", "actor", "createdAt"] };
    const columns = fields[tab] ?? [];
    return <div className="admin-table-wrap"><table className="admin-table"><thead><tr>{columns.map(key => <th key={key}>{key}</th>)}</tr></thead><tbody>{rows.map(row => <tr key={row.id}>{columns.map(key => { const value = row[key]; const cell = value && typeof value === "object" ? value.name ?? value.displayName ?? value.title ?? "—" : String(value ?? "—"); return <td key={key}>{key.toLowerCase().includes("date") || key.toLowerCase().includes("at") ? (value ? new Date(value).toLocaleString("ru-KZ") : "—") : cell}</td>; })}</tr>)}</tbody></table></div>;
  };
  const setSetting = (group: "arbitration" | "advertising", key: string, value: unknown) => setSettings((current: any) => ({ ...current, [group]: { ...current[group], [key]: value } }));
  return <div className="portal-shell"><PortalHeader title="Панель администратора" role="Администратор" /><div className="portal-layout"><aside className="admin-sidebar"><Brand compact /><div className="sidebar-section-label">Платформа</div>{tabs.map(item => { const Icon = item.icon; return <button key={item.key} className={`sidebar-link ${tab === item.key ? "active" : ""}`} onClick={() => setTab(item.key)}><Icon size={17} /><span>{item.label}</span>{item.key === "disputes" && overview?.activeDisputes ? <span className="sidebar-count">{overview.activeDisputes}</span> : null}{item.key === "subcontracts" && overview?.activeSubcontracts ? <span className="sidebar-count">{overview.activeSubcontracts}</span> : null}</button>; })}<div className="sidebar-bottom"><Link to="/" className="sidebar-link"><Home size={18} /><span>На сайт</span></Link></div></aside><main className="admin-main"><div className="breadcrumbs"><span>Администрирование</span><ChevronRight size={14} /><span>{title}</span></div><div className="customer-welcome"><div><span className="section-eyebrow">Рабочее пространство</span><h1>{tab === "overview" ? "Обзор платформы" : title}</h1><p>Данные и действия загружаются из API и сохраняются в журнале аудита.</p></div><button className="button button-secondary" onClick={exportRows}><ArrowDown size={15} />Экспорт JSON</button></div>{tab === "overview" && overview && <div className="admin-stats">{[["Пользователи", overview.users], ["Открытые заявки", overview.openRequests], ["Сделки", overview.activeDeals], ["Субподряды", overview.activeSubcontracts ?? 0], ["Споры", overview.activeDisputes], ["Поставщики на проверке", overview.pendingSuppliers]].map(([label, value]) => <div key={label}><span>{label}</span><strong>{value}</strong><small>Текущие данные платформы</small></div>)}</div>}{loading ? <div className="empty-state">Загружаем раздел…</div> : error ? <div className="empty-state"><strong>Нет доступа или ошибка загрузки</strong><span>{error}</span>{!readLocal("tm_access_token", "") && <Link to="/auth" className="button button-primary">Войти</Link>}<button className="button button-secondary" onClick={() => void load()}>Повторить</button></div> : tab === "settings" ? <div className="supplier-manage-grid"><section className="admin-panel manage-form"><h2>Арбитраж</h2><label className="manage-publish"><input type="checkbox" checked={Boolean(settings.arbitration?.enabled)} onChange={event => setSetting("arbitration", "enabled", event.target.checked)} />Включить платный тариф</label><label><span>Стоимость, ₸</span><input type="number" min="0" value={settings.arbitration?.feeKzt ?? 0} onChange={event => setSetting("arbitration", "feeKzt", Number(event.target.value))} /></label><label><span>Бесплатно до</span><input type="date" value={settings.arbitration?.freeUntil?.slice?.(0, 10) ?? ""} onChange={event => setSetting("arbitration", "freeUntil", event.target.value || null)} /></label><button className="button button-primary" onClick={() => saveSettings("arbitration")}>Сохранить тариф</button></section><section className="admin-panel manage-form"><h2>Реклама</h2><label><span>Минимальный бюджет, ₸</span><input type="number" min="0" value={settings.advertising?.minimumBudgetKzt ?? 0} onChange={event => setSetting("advertising", "minimumBudgetKzt", Number(event.target.value))} /></label><label><span>Обычная длительность, дней</span><input type="number" min="1" max="365" value={settings.advertising?.defaultDurationDays ?? 30} onChange={event => setSetting("advertising", "defaultDurationDays", Number(event.target.value))} /></label><button className="button button-primary" onClick={() => saveSettings("advertising")}>Сохранить тарифы</button></section></div> : tab === "overview" ? <section className="admin-panel"><div className="dashboard-section-head"><h2>Сводка по платформе</h2><span>обновлено сейчас</span></div><p className="admin-overview-note">Откройте раздел слева для управления пользователями, категориями, товарами, отзывами, спорами и рекламой.</p></section> : <section className="admin-panel"><div className="dashboard-section-head"><h2>{title}</h2><span>{rows.length} записей · последние 100</span></div>{rows.length ? renderRows() : <div className="empty-state">В этом разделе пока нет записей.</div>}</section>}{notice && <div className="inline-notice success-notice">{notice}</div>}{error && <div className="inline-notice" role="alert">{error}</div>}<div className="admin-audit"><ShieldCheck size={18} /><span><strong>Операционные действия журналируются</strong><small>Изменения пользователей, тарифов, рекламы, категорий и арбитража записываются в аудит.</small></span><button className="text-link-button" onClick={() => setTab("audit")}>Открыть аудит <ArrowRight size={14} /></button></div></main></div></div>;
}
function AuthPage() {
  const [mode, setMode] = useState<"login" | "register">("login");
  const [role, setRole] = useState("customer");
  const [message, setMessage] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [displayName, setDisplayName] = useState("");
  const [organizationName, setOrganizationName] = useState("");
  const navigate = useNavigate();
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setMessage("");
    try {
      const endpoint = mode === "register" ? "/auth/register" : "/auth/login";
      const payload = mode === "register" ? { email, password, displayName, role, organizationName: organizationName || undefined } : { login: email, password };
      const session = await apiRequest<{ accessToken: string; refreshToken: string; user: { id: string; role: string } }>(endpoint, { method: "POST", body: JSON.stringify(payload) });
      window.localStorage.setItem("tm_access_token", session.accessToken);
      window.localStorage.setItem("tm_refresh_token", session.refreshToken);
      window.localStorage.setItem("tm_user_id", session.user.id);
      window.localStorage.setItem("tm_user_role", session.user.role);
      navigate(session.user.role === "SUPPLIER" ? "/supplier/inbox" : session.user.role === "ARBITER" ? "/arbiter" : session.user.role === "ADMIN" ? "/admin" : "/customer");
    } catch (error) { setMessage(error instanceof Error ? error.message : "Не удалось войти. Проверьте данные и повторите попытку."); }
  };
  return <><SiteHeader /><main className="auth-page"><section className="auth-card"><Brand /><span className="section-eyebrow">Площадка закупок</span><h1>{mode === "login" ? "С возвращением" : "Создайте аккаунт"}</h1><p>Войдите, чтобы продолжить работу с заявками и предложениями.</p><div className="auth-mode"><button type="button" className={mode === "login" ? "active" : ""} onClick={() => { setMode("login"); setMessage(""); }}>Войти</button><button type="button" className={mode === "register" ? "active" : ""} onClick={() => { setMode("register"); setMessage(""); }}>Регистрация</button></div><form onSubmit={submit}>{mode === "register" && <label><span>Ваше имя</span><input value={displayName} onChange={event => setDisplayName(event.target.value)} required minLength={2} placeholder="Анна Султанова" /></label>}<label><span>Электронная почта</span><input type="email" value={email} onChange={event => setEmail(event.target.value)} required placeholder="name@company.kz" /></label><label><span>Пароль</span><input type="password" value={password} onChange={event => setPassword(event.target.value)} required minLength={10} placeholder="Не менее 10 символов" /></label>{mode === "register" && <><label><span>Я хочу</span><select value={role} onChange={event => setRole(event.target.value)}><option value="customer">Покупать товары</option><option value="supplier">Продавать товары</option></select></label>{role === "supplier" && <label><span>Название компании</span><input value={organizationName} onChange={event => setOrganizationName(event.target.value)} placeholder="ТОО «Название»" /></label>}</>}{message && <div className="form-error" role="alert">{message}</div>}<button className="button button-primary full-button">{mode === "login" ? "Войти в аккаунт" : "Создать аккаунт"}<ArrowRight size={16} /></button></form><small className="auth-terms">Продолжая, вы принимаете условия использования и политику конфиденциальности.</small></section></main><Footer /></>;
}

export function App() {
  return <Routes><Route path="/" element={<HomePage />} /><Route path="/catalog" element={<CatalogPage />} /><Route path="/suppliers" element={<SuppliersPage />} /><Route path="/subcontracts" element={<SubcontractsPage />} /><Route path="/supplier/inbox" element={<SupplierWorkspaceLive />} /><Route path="/supplier/products" element={<SupplierProductsPage />} /><Route path="/supplier/ads" element={<SupplierAdsPage />} /><Route path="/request/new" element={<NewRequestPage />} /><Route path="/customer" element={<CustomerDashboard />} /><Route path="/requests/:id/offers" element={<OfferComparisonLive />} /><Route path="/deals/:id" element={<DealPageLive />} /><Route path="/arbiter" element={<ArbiterPage />} /><Route path="/admin/*" element={<AdminPage />} /><Route path="/auth" element={<AuthPage />} /><Route path="*" element={<HomePage />} /></Routes>;
}






